// 做加密盘 / 解密盘：在浏览器里边读边加密（解密），直接写成这台电脑上的文件 —— created 20261014 by Claude Opus 5.5
// user 10-14：「如何能不经过你准备盘？有没有不需要背命令行的工具」→ 方案 C「C同意…解密盘也要做」。
// 和命令行导入工具（scripts/import-disc.ts）出同一种 KRD2 容器（元数据在头：先占位、写完正文回填）；整盘永远不进内存（按块读、按块写）。
// 要能直接写本机文件（showSaveFilePicker）：电脑上的 Chrome / Edge 有；iPad / Quest 的浏览器没有 → 入口说明白、不假装能用。
// 浏览器算不了分段 sha256，所以这里做的盘元数据里没有 sha256（字段本来就是可选的；命令行工具做的有）。盘号 / 版本照样从 PARAM.SFO 读进元数据。
import { beginDisc, openDisc, type ByteSource, type DiscFingerprint } from "../disc/crypt.ts";
import { readDiscLabel } from "../disc/sfo.ts";
import { PLATFORM_CODE } from "./config.ts";
import { getStore } from "./app-store.ts";

const CHUNK = 8 * 2 ** 20; // 16 的倍数（CTR 分块要求）

export const canWriteLocalFiles = (): boolean => typeof globalThis.showSaveFilePicker === "function" && typeof globalThis.showOpenFilePicker === "function";

export interface Progress {
  update(done: number, total: number): void;
  /** 人点了取消。 */
  readonly cancelled: boolean;
}

export class Cancelled extends Error {
  constructor() { super("cancelled"); this.name = "Cancelled"; }
}

/** 随机 16 位十六进制（和导入工具同样的起名：文件名不透露是什么）。 */
export function randomStem(): string {
  return Array.from(crypto.getRandomValues(new Uint8Array(8)), (b) => b.toString(16).padStart(2, "0")).join("");
}

/** 写的过程中出任何事（包括取消）都丢掉半成品，不留一个坏文件（interrupt = cancel）。 */
async function writeAll(out: FileSystemFileHandle, body: (w: FileSystemWritableFileStream) => Promise<void>): Promise<void> {
  const w = await out.createWritable();
  try {
    await body(w);
    await w.close();
  } catch (e) {
    await w.abort().catch(() => {});
    throw e;
  }
}

/** 「上传盘」：边加密边传进食品柜，不留本机副本（store 0.17.0 files.uploadStream；user 10-14 方案 A）。
 *  头部（元数据：原名、盘号 / 版本）事先封好，上传器按偏移要块：头部区直接给、正文区现场 CTR 加密（随机访问，不用顺序喂）。
 *  整盘不进内存；撞名 / 离线 / 没登录由库抛错；中途断了云端没有半成品（上传会话最后一块落地才成文件）。sha256 浏览器算不了，不写。 */
export async function uploadToPantry(input: File, password: string, identifier: string, onProgress: (done: number, total: number) => void): Promise<void> {
  const src: ByteSource = { size: input.size, read: async (o, n) => new Uint8Array(await input.slice(o, o + n).arrayBuffer()) };
  const label = await readDiscLabel(src);
  const fp: DiscFingerprint = { k: PLATFORM_CODE.psp, size: input.size, ...(label?.id ? { id: label.id } : {}), ...(label?.version ? { v: label.version } : {}) };
  const writer = await beginDisc(password, { size: input.size });
  const head = await writer.finish({ name: input.name, fp });
  const total = head.length + input.size;
  const source = {
    size: total,
    async read(offset: number, length: number): Promise<Uint8Array> {
      const out = new Uint8Array(length);
      let o = 0;
      if (offset < head.length) { const n = Math.min(length, head.length - offset); out.set(head.subarray(offset, offset + n), 0); o = n; }
      if (o < length) {
        const bodyOff = offset + o - head.length; // 正文偏移；上传器按 5 MiB 对齐要块，正文偏移保持 16 对齐
        if (bodyOff % 16 !== 0) throw new RangeError(`upload chunk not 16-aligned at body offset ${bodyOff}`);
        const plain = new Uint8Array(await input.slice(bodyOff, bodyOff + (length - o)).arrayBuffer());
        out.set(await writer.encryptAt(bodyOff, plain), o);
      }
      return out;
    },
  };
  await getStore().files.uploadStream(identifier, source, { onProgress });
}

export async function encryptToLocal(input: File, password: string, out: FileSystemFileHandle, p: Progress): Promise<void> {
  const src: ByteSource = { size: input.size, read: async (o, n) => new Uint8Array(await input.slice(o, o + n).arrayBuffer()) };
  const label = await readDiscLabel(src);
  const fp: DiscFingerprint = { k: PLATFORM_CODE.psp, size: input.size, ...(label?.id ? { id: label.id } : {}), ...(label?.version ? { v: label.version } : {}) };
  const writer = await beginDisc(password);
  await writeAll(out, async (w) => {
    await w.write(new Uint8Array(writer.headBytes) as FileSystemWriteChunkType); // 先占位
    for (let off = 0; off < input.size; off += CHUNK) {
      if (p.cancelled) throw new Cancelled();
      const plain = new Uint8Array(await input.slice(off, off + CHUNK).arrayBuffer());
      await w.write(await writer.encrypt(plain) as FileSystemWriteChunkType);
      p.update(Math.min(off + CHUNK, input.size), input.size);
    }
    await w.write({ type: "write", position: 0, data: await writer.finish({ name: input.name, fp }) } as FileSystemWriteChunkType); // 回填头部
  });
}

/** 先打开（验口令、拿原文件名），再决定写到哪：口令不对抛 WrongPasswordError。 */
export async function openForDecrypt(input: File, password: string): Promise<{ name: string; size: number; write(out: FileSystemFileHandle, p: Progress): Promise<void> }> {
  const src: ByteSource = { size: input.size, read: async (o, n) => new Uint8Array(await input.slice(o, o + n).arrayBuffer()) };
  const disc = await openDisc(src, password);
  return {
    name: disc.meta.name ?? `${input.name.replace(/\.[^.]*$/, "")}.iso`,
    size: disc.size,
    async write(out, p) {
      await writeAll(out, async (w) => {
        for (let off = 0; off < disc.size; off += CHUNK) {
          if (p.cancelled) throw new Cancelled();
          await w.write(await disc.read(off, CHUNK) as FileSystemWriteChunkType);
          p.update(Math.min(off + CHUNK, disc.size), disc.size);
        }
      });
    },
  };
}
