// 云同步状态：正在传什么、传了多久、卡没卡、有几个没传上去——画在主界面上，不是一闪而过的提示 —— created 20261014 by Claude Fable 5.1
// user 10-14：「云存档上传状态应该主界面可视化而不是一个不明不白的toaster。然后也许游玩界面也会有一个顶的进度条吧」「卡住了就红色」。
// 游玩界面：#stage 顶部一条细条 + 一个小标签（在 #stage 里，所以全屏也看得见）；主页：账户行下面一行字。
// 单个上传的进度 store 不吐（库接口没有 onProgress），所以条是「在传 / 卡住 / 失败」三态 + 已用秒数；要真进度得改库。
// 顺带当黑匣子：每次开始 / 结束 / 出错 / 冲突都记一行（内存里最近 300 条），存档管理里能看、能复制——下次「存档丢了」有据可查。
import { $, h, errorText } from "./ui.ts";

export interface SaveOutcome { pushed: boolean; reason?: string }
interface Flight { id: number; label: string; bytes: number; startedAt: number; /** 传到哪了（store 0.17.0 的 onProgress）；没有 = 不知道，条子画成不定长。 */ done: number | null; /** 传 / 下载 */ verb: string; /** 最近一次有进度的时刻。 */ progressAt?: number }
interface Entry { at: number; level: "info" | "warn" | "error"; text: string }

/** 传了这么久还没好就标红（上行慢的网络上 10 MB 快照也该在这之内传完）。 */
const STUCK_MS = 45_000;
const LOG_MAX = 300;

const flights = new Map<number, Flight>();
let nextId = 1;
let pending = 0;
let problem: { text: string; at: number } | null = null;
/** 本机这一步（核吐状态 / 压 / 封 / 写 IDB）：上传之前的那几百毫秒到几秒，也要有状态（user 10-14「存档中不要做成toast，而是一个常驻的状态显示」）。 */
let local: { label: string; startedAt: number } | null = null;
let doneUntil = 0; // 传好了之后绿一会儿再回到空闲
/** 累计传了多少字节（上传 = 快照 / 存档 / 上传盘；下载 = 缓存全盘）：工具栏的实时网络读数按秒差算速率。读盘的下载另由核统计。 */
export const netBytes = { up: 0, down: 0 };
/** 网络抖动造成的没传上去：字节在本机、会自动再传 → 黄，不是红；传成功一次就清掉。 */
let softProblem: { text: string; at: number } | null = null;
let retryHook: (() => void) | null = null;
/** 有网络抖动时调（store-ui 的错误漏斗）：记一笔、状态条变黄、安排一次自动再传。 */
export function networkHiccup(detail: string): void {
  softProblem = { text: "网络断了一下，没传上去：存在这台设备了，联网后自动再传", at: Date.now() };
  logEvent("warn", `网络：${detail}`);
  retryHook?.();
}
/** 安排自动再传的钩子（main.ts 给：15 s 后推一次没传上去的）。 */
export function onRetryWanted(fn: () => void): void { retryHook = fn; }
/** 读盘在等网（锁屏解锁 / 断网时）：状态条最优先显示，红。 */
let readWait: string | null = null;
export function setReadWait(text: string | null): void { if (text !== readWait) { readWait = text; if (text) logEvent("warn", text); else render(); } }
const log: Entry[] = [];
let onClick: (() => void) | null = null;
let signedIn: () => boolean = () => true;
let timer = 0;
const listeners = new Set<(s: SyncState) => void>();

export type SyncKind = "idle" | "saving" | "busy" | "stuck" | "bad" | "pending" | "done" | "local";
export interface SyncState { kind: SyncKind; text: string; /** 0–1 = 真进度；null = 不知道（条子画成不定长动画）。 */ fraction?: number | null }

/** 状态一变就通知（smart save button 用）；返回退订。 */
export function subscribe(cb: (s: SyncState) => void): () => void { listeners.add(cb); cb(state()); return () => { listeners.delete(cb); }; }
/** 有东西正在存 / 传（退出、刷新、关页前要等它）。 */
export const inFlight = (): boolean => !!local || flights.size > 0;
/** 还「活着」的在途传输：开始不到 90 s、或 90 s 内有过进度。卡死的（iOS 锁屏后 fetch 永远不结束）不算，别让它挡住续推。 */
export function inFlightFresh(): boolean {
  if (local) return true;
  const now = performance.now();
  for (const f of flights.values()) if (now - Math.max(f.startedAt, f.progressAt ?? f.startedAt) < 90_000) return true;
  return false;
}
/** 等到没有东西在存 / 传。 */
export function whenIdle(): Promise<void> {
  if (!inFlight()) return Promise.resolve();
  return new Promise((resolve) => { const off = subscribe(() => { if (!inFlight()) { off(); resolve(); } }); });
}
export function beginLocal(label: string): void { local = { label, startedAt: performance.now() }; render(); }
export function endLocal(): void { local = null; render(); }

const mb = (n: number) => (n >= 2 ** 20 ? `${(n / 2 ** 20).toFixed(1)} MB` : `${(n / 1024).toFixed(0)} KB`);
const secs = (t0: number) => `${((performance.now() - t0) / 1000).toFixed(0)} s`;

export function logEvent(level: Entry["level"], text: string): void {
  log.push({ at: Date.now(), level, text });
  if (log.length > LOG_MAX) log.shift();
  (level === "info" ? console.info : console.warn)("[sync]", text);
  render();
}

/** 跟一次上传：开始、结束（推上没推上）、出错都记下并画出来。run 拿到 onProgress（传给 store 的 save / uploadStream）。 */
export function track<T extends SaveOutcome>(label: string, bytes: number, run: (onProgress: (done: number, total: number) => void) => Promise<T>, verb = "传"): Promise<T> {
  const id = nextId++;
  const f: Flight = { id, label, bytes, startedAt: performance.now(), done: null, verb };
  flights.set(id, f);
  logEvent("info", `开始传 ${label}（${mb(bytes)}）`);
  let lastPaint = 0;
  const p = run((done, total) => {
    const delta = Math.max(0, done - (f.done ?? 0));
    if (f.verb === "传") netBytes.up += delta; else netBytes.down += delta;
    f.done = done; if (total) f.bytes = total; f.progressAt = performance.now();
    const now = performance.now();
    if (now - lastPaint > 200 || done === total) { lastPaint = now; render(); }
  });
  return p.then((r) => {
    flights.delete(id);
    if (r.pushed) { problem = null; softProblem = null; doneUntil = performance.now() + 3000; logEvent("info", `传好了 ${label}，用了 ${secs(f.startedAt)}`); }
    else if (!signedIn()) { problem = null; doneUntil = performance.now() + 3000; logEvent("info", `${label} 存在这台设备（没登录，不传）`); }
    else if (r.reason === "not-attempted") { problem = null; doneUntil = performance.now() + 3000; logEvent("info", `${label} 存在这台设备了（锁屏 / 后台不传，回来自动传）`); retryHook?.(); }
    else if (r.reason === "error" || r.reason === "deferred") { softProblem = { text: `${label} 没传上去（网络？）：存在这台设备了，会自动再传`, at: Date.now() }; logEvent("warn", softProblem.text); retryHook?.(); }
    else { problem = { text: `${label} 没传上去（${r.reason ?? "原因不明"}）`, at: Date.now() }; logEvent("warn", problem.text); }
    return r;
  }, (e: unknown) => {
    flights.delete(id);
    problem = { text: `${label} 出错：${errorText(e)}`, at: Date.now() };
    logEvent("error", problem.text);
    throw e;
  });
}

/** 没传上去 / 冲突 / 云端没了的文件有几个（存档管理那套 needsAttention 的计数，由文件夹订阅喂）。 */
export function setPending(n: number): void { pending = n; if (n === 0) softProblem = null; render(); }

export function dumpLog(): string {
  return log.map((e) => `${new Date(e.at).toLocaleTimeString()} ${e.level === "info" ? " " : e.level === "warn" ? "!" : "✖"} ${e.text}`).join("\n") || "（还没有记录）";
}

/** 装到页面上：#syncbar（游玩界面 #stage 里）、#sync-home（主页）。点它 = 打开存档管理。 */
export function mount(opts: { onClick: () => void; signedIn: () => boolean }): void {
  onClick = opts.onClick;
  signedIn = opts.signedIn;
  for (const id of ["syncbar", "sync-home"]) $(id).addEventListener("click", () => onClick?.());
  render();
}

export function state(): SyncState {
  if (readWait) return { kind: "stuck", text: readWait };
  if (local) return { kind: "saving", text: `正在存 ${local.label}…` };
  const first = flights.values().next().value as Flight | undefined;
  if (first) {
    const elapsed = performance.now() - first.startedAt;
    const more = flights.size > 1 ? `（还有 ${flights.size - 1} 个排着）` : "";
    const pct = first.done != null && first.bytes ? ` ${Math.floor((first.done / first.bytes) * 100)}%` : "";
    const fraction = first.done != null ? first.done / first.bytes : null;
    // 大下载（缓存全盘几百 MB）几分钟很正常：只在 45 s 内一点进度都没有时才算卡住
    const stuck = elapsed > STUCK_MS && (first.done == null || first.done === 0 || first.bytes < 64 * 2 ** 20);
    if (stuck) return { kind: "stuck", text: `卡住了？${first.label} 已经${first.verb}了 ${secs(first.startedAt)}${pct}${more}`, fraction };
    return { kind: "busy", text: `正在${first.verb} ${first.label} ${mb(first.bytes)}${pct} · ${secs(first.startedAt)}${more}`, fraction };
  }
  if (problem) return { kind: "bad", text: problem.text };
  if (softProblem && pending > 0) return { kind: "pending", text: softProblem.text };
  if (performance.now() < doneUntil) return signedIn() ? { kind: "done", text: "传好了" } : { kind: "local", text: "存在这台设备了（没登录，不传）" };
  if (!signedIn()) return pending > 0 ? { kind: "local", text: `${pending} 个只在这台设备（登录后再传）` } : { kind: "idle", text: "没登录：存档只在这台设备" };
  if (pending > 0) return { kind: "pending", text: `${pending} 个没传上去 / 要处理` };
  return { kind: "idle", text: "云端：已同步" };
}

function render(): void {
  const s = state();
  for (const cb of listeners) cb(s);
  const bar = document.getElementById("syncbar"), home = document.getElementById("sync-home");
  if (bar) {
    bar.className = `syncbar ${s.kind}${s.fraction != null ? " known" : ""}`;
    bar.hidden = s.kind === "idle";
    const fill = h("span", { class: "syncbar-fill" });
    if (s.fraction != null) fill.style.width = `${Math.max(2, Math.min(100, s.fraction * 100)).toFixed(1)}%`;
    bar.replaceChildren(h("span", { class: "syncbar-track" }, fill), h("span", { class: "syncbar-text" }, s.text));
  }
  if (home) { home.className = `sync-home ${s.kind}`; home.hidden = false; home.textContent = s.text; }
  const live = local || flights.size || performance.now() < doneUntil;
  if (live && !timer) timer = window.setInterval(() => { if (!(local || flights.size || performance.now() < doneUntil)) { clearInterval(timer); timer = 0; } render(); }, 1000);
}
