// 界面小零件：图标、面板（sheet）、横条、全屏遮罩、状态提示 —— created 20261014 by Claude Opus 5.5
// 家规：不用系统 alert / prompt / confirm；图标只用家族图标库（assets/icons.svg，extract-icons.py 生成）。
import sprite from "../../assets/icons.svg";

export const $ = <T extends HTMLElement = HTMLElement>(id: string): T => {
  const el = document.getElementById(id);
  if (!el) throw new Error(`missing #${id}`);
  return el as T;
};

export function mountIcons(): void {
  const holder = document.createElement("div");
  holder.innerHTML = sprite;
  document.body.prepend(holder.firstElementChild!);
}

export function icon(name: string): SVGSVGElement {
  const svg = document.createElementNS("http://www.w3.org/2000/svg", "svg");
  svg.setAttribute("class", "icon");
  svg.setAttribute("aria-hidden", "true");
  const use = document.createElementNS("http://www.w3.org/2000/svg", "use");
  use.setAttribute("href", `#${name}`);
  svg.append(use);
  return svg;
}

type Child = Node | string | null | undefined | false;
export function h<K extends keyof HTMLElementTagNameMap>(tag: K, attrs: Record<string, unknown> = {}, ...children: Child[]): HTMLElementTagNameMap[K] {
  const el = document.createElement(tag);
  for (const [k, v] of Object.entries(attrs)) {
    if (v == null || v === false) continue;
    if (k.startsWith("on") && typeof v === "function") el.addEventListener(k.slice(2), v as EventListener);
    else if (k === "class") el.className = String(v);
    else el.setAttribute(k, v === true ? "" : String(v));
  }
  for (const c of children) if (c) el.append(c);
  return el;
}

// ── 面板：一次只开一个；Esc / 点背景 = 取消（返回 null）──
let openSheet: { close: (v: unknown) => void } | null = null;

export function sheet<T>(build: (done: (v: T | null) => void) => Node[], opts: { dismissable?: boolean } = {}): Promise<T | null> {
  openSheet?.close(null);
  return new Promise<T | null>((resolve) => {
    const back = h("div", { class: "sheet-back" });
    const box = h("div", { class: "sheet", role: "dialog" });
    let finished = false;
    const done = (v: T | null) => {
      if (finished) return;
      finished = true;
      back.remove();
      removeEventListener("keydown", onKey, true);
      if (openSheet === handle) openSheet = null;
      resolve(v);
    };
    const handle = { close: (v: unknown) => done(v as T | null) };
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape" && opts.dismissable !== false) { e.preventDefault(); e.stopPropagation(); done(null); }
      else e.stopPropagation(); // 面板开着时按键不进游戏
    };
    if (opts.dismissable !== false) back.addEventListener("pointerdown", (e) => { if (e.target === back) done(null); });
    addEventListener("keydown", onKey, true);
    box.append(...build(done));
    back.append(box);
    overlayHost().append(back); // 全屏时挂在全屏元素里，否则看不见（10-14 user「存档成功没有toast」= 全屏把口令 / 冲突面板也一起盖掉了）
    openSheet = handle;
    (box.querySelector("input, button.primary") as HTMLElement | null)?.focus();
  });
}

export const isSheetOpen = (): boolean => openSheet !== null;

// ── 浮层挂在哪：全屏元素之外的东西浏览器一律不画。横条 / 提示 / 更新 / 遮罩 / 面板进全屏时搬进去，退出再搬回来。added 20261014 by Claude Fable 5.1
const OVERLAY_IDS = ["banners", "note", "update", "busy"];
const overlayHost = (): HTMLElement => (document.fullscreenElement as HTMLElement | null) ?? document.body;
export function mountOverlays(): void {
  document.addEventListener("fullscreenchange", () => {
    const host = overlayHost();
    for (const id of OVERLAY_IDS) host.append($(id));
    for (const back of Array.from(document.querySelectorAll(".sheet-back"))) host.append(back);
  });
}

let rememberChoice = false;
/** 上一次口令面板里「在这台设备上记住」勾没勾（取一次就清）。 */
export function takeRememberChoice(): boolean { const v = rememberChoice; rememberChoice = false; return v; }

/** 问口令。默认只在这次打开的页面里用；offerRemember = 给一个「在这台设备上记住」的勾（默认不勾；user 10-15 拍板，见 remember-password.ts）。 */
export function askPassword(title: string, hint = "", opts: { offerRemember?: boolean } = {}): Promise<string | null> {
  rememberChoice = false;
  return sheet<string>((done) => {
    const input = h("input", { type: "password", autocomplete: "off", spellcheck: "false" });
    const remember = opts.offerRemember ? (h("input", { type: "checkbox" }) as HTMLInputElement) : null;
    const submit = () => { if (input.value) { rememberChoice = !!remember?.checked; done(input.value); } };
    input.addEventListener("keydown", (e) => { if (e.key === "Enter") { e.preventDefault(); submit(); } });
    return [
      h("h2", {}, title),
      hint ? h("p", { class: "hint" }, hint) : null,
      input,
      remember ? h("label", { class: "remember-row" }, remember, h("span", {}, "在这台设备上记住"), h("span", { class: "hint" }, "能解锁这台设备的人就能打开你的东西")) : null,
      h("div", { class: "row" },
        h("button", { onclick: () => done(null) }, "取消"),
        h("button", { class: "primary", onclick: submit }, "确定")),
    ].filter(Boolean) as Node[];
  });
}

export function confirmSheet(title: string, text: string, ok: string, cancel = "取消"): Promise<boolean> {
  return sheet<boolean>((done) => [
    h("h2", {}, title),
    h("p", {}, text),
    h("div", { class: "row" },
      h("button", { onclick: () => done(false) }, cancel),
      h("button", { class: "primary", onclick: () => done(true) }, ok)),
  ]).then((v) => v === true);
}

// ── 横条（错误 / 警告，要人看见；点叉关）──
export function banner(text: string, level: "error" | "warning" = "error"): void {
  const host = $("banners");
  const close = h("button", { class: "icon-btn", title: "关闭" }, icon("x"));
  const el = h("div", { class: `banner ${level}` }, h("span", {}, text), close);
  close.addEventListener("click", () => el.remove());
  host.append(el);
}

// ── 状态提示（一行，几秒后淡出）──
let noteTimer = 0;
export function note(text: string, ms = 4000): void {
  const el = $("note");
  el.textContent = text;
  el.hidden = false;
  clearTimeout(noteTimer);
  noteTimer = window.setTimeout(() => { el.hidden = true; }, ms);
}

// ── 全屏遮罩（store 的写操作在里面跑，吞掉输入）──
let busyDepth = 0;
export async function withBusy<T>(label: string, fn: () => Promise<T>): Promise<T> {
  const el = $("busy");
  busyDepth++;
  el.querySelector("span")!.textContent = label;
  el.hidden = false;
  try { return await fn(); } finally { if (--busyDepth === 0) el.hidden = true; }
}

/** 网络类失败（断网、iOS 切网络、VPN 抖动、上传中途掉线）：字节都还在本机，稍后会自动再传，不该当成要人处理的错误。 */
export function isNetworkError(e: unknown): boolean {
  const x = e as { name?: string; message?: string } | null;
  return x?.name === "CloudNetworkError" || /network fetch failed|Load failed|Failed to fetch|NetworkError/i.test(x?.message ?? "");
}

export function errorText(e: unknown): string {
  if (isNetworkError(e)) return "网络断了一下（连不上 OneDrive）";
  if (e instanceof Error) return e.message;
  return String(e);
}
