// 这台设备自己的几个标量（不上云）：全 app **唯一**允许碰 localStorage 的文件（家族 device-kv 器官，形状照 WeebPaint src/device-kv.ts）—— created 20261014 by Claude Fable 5.1
// 键带 app 前缀（同 origin 的兄弟 PWA 不串）；读写都 try/catch（隐私模式 / 配额 / 被禁用 → 内存兜底）。
// 现在只有一项：本机流式暂存区上限（user 10-14「cache上限设置」）。加键 = 新的持久化结构，要先问 user。
import { APP_ID } from "./config.ts";

const PREFIX = `${APP_ID}.device.`;
const mem = new Map<string, string>();

function get(key: string): string | null {
  try { return localStorage.getItem(PREFIX + key) ?? mem.get(key) ?? null; } catch { return mem.get(key) ?? null; }
}
function set(key: string, value: string | null): void {
  if (value == null) mem.delete(key); else mem.set(key, value);
  try { if (value == null) localStorage.removeItem(PREFIX + key); else localStorage.setItem(PREFIX + key, value); } catch { /* 内存兜底 */ }
}

/** 流式暂存区上限的几档（字节）。0 = 库默认（256 MiB）。 */
export const STAGING_CAP_CHOICES: { label: string; bytes: number }[] = [
  { label: "256 MB（默认）", bytes: 0 },
  { label: "1 GB", bytes: 1 * 2 ** 30 },
  { label: "4 GB", bytes: 4 * 2 ** 30 },
  { label: "16 GB", bytes: 16 * 2 ** 30 },
];
export function stagingCapBytes(): number {
  const n = Number(get("staging-cap") ?? 0);
  return Number.isFinite(n) && n > 0 ? n : 0;
}
export function setStagingCapBytes(bytes: number): void { set("staging-cap", bytes > 0 ? String(bytes) : null); }
