// store 的冲突面、回收站只拿得到身份（`jars/3f9a….jam`），人看不懂。存档 / 快照模块在知道对应关系的时候登记一下，
// 面板显示时来查。没登记过的退回到按身份猜一个泛称。这个模块故意零依赖（store-ui ↔ saves 之间不绕成环）。
const labels = new Map<string, string>();

export const setLabel = (identifier: string, label: string): void => { labels.set(identifier, label); };

/** 身份的可读名：登记过的用登记的，否则按文件夹 / 后缀给个泛称。 */
export function labelFor(identifier: string): string {
  const known = labels.get(identifier);
  if (known) return known;
  const m = /^crumbs\/[0-9a-f]{16}-([sa])([0-9]+)\.crumb$/.exec(identifier);
  if (m) return `快照（${m[1] === "s" ? "手动" : "自动"} ${m[2]}）`;
  if (identifier.startsWith("jars/")) return "存档";
  if (identifier.startsWith("pantry/")) return "盘";
  return identifier.replace(/^.*\//, "");
}
