// 「在这台设备上记住口令」—— created 20261015 by Claude Fable 5.1
// user 10-15：「还是允许设备记住密码，每次进来不用输吧。你看我claude都可以直接进……仔细想想安全问题」→ 分析在 ai-docs/20261014-wishlist.md W-24 →
//   user「做法：按设备 opt-in（口令面板一个勾「在这台设备上记住」，默认不勾）好，那么做，同意」。
// 这是对 ADR-0012「口令只在内存、永不持久化」的有意吃书（user 拍板）。威胁模型：加密防的是云端那一方；拿着已解锁设备的人本来就什么都看得见
//   （OneDrive app、浏览器都登着）——设备记住口令不新增信任方，新增的只是「时间」。
// 规矩：
//   · 全 app 只有这个文件碰库 `kudsrocket.remember`（家规：app 自开 IDB 逐案批；这次 user 10-15 批的）。不同步、不上云、不是正本。
//   · 盘上**没有明文口令**：口令用一把存在同一个库里的**不可导出** AES-GCM 钥匙封起来再存。同源脚本能用那把钥匙解（和它能读到这一页内存里的口令一样），
//     但拿不走钥匙本身；别的 origin、别的 app 碰不到。设备锁 + 系统的文件保护管盘上那份。
//   · 默认不记；记了之后主页上一直有「忘记」；清本机缓存 / 强制更新**不**清它（它不是缓存）。记着的口令打不开东西（别处换过口令）→ 调用方 forget。
//   · 三个 app（WeebPaint / WXHW / 本仓）都要这个：这里写成零依赖的纯模块，以后提成共享库时整文件搬走。
const DB_NAME = "kudsrocket.remember";
const STORE = "secret";
const KEY = "password";

interface Record_ { key: CryptoKey; iv: Uint8Array; ct: ArrayBuffer }

let dbp: Promise<IDBDatabase> | null = null;
function db(): Promise<IDBDatabase> {
  dbp ??= new Promise((resolve, reject) => {
    const req = indexedDB.open(DB_NAME, 1);
    req.onupgradeneeded = () => { req.result.createObjectStore(STORE); };
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error);
  });
  dbp.catch(() => { dbp = null; });
  return dbp;
}
/** 一个事务：complete 才 resolve（写在配额墙上可能 success 之后又 abort，不能当成功）。 */
async function tx<T>(mode: IDBTransactionMode, body: (s: IDBObjectStore) => IDBRequest<T> | void): Promise<T | undefined> {
  const d = await db();
  return new Promise<T | undefined>((resolve, reject) => {
    const t = d.transaction(STORE, mode);
    let result: T | undefined;
    const req = body(t.objectStore(STORE));
    if (req) req.onsuccess = () => { result = req.result; };
    t.oncomplete = () => resolve(result);
    t.onerror = () => reject(t.error);
    t.onabort = () => reject(t.error ?? new Error("remember-password transaction aborted"));
  });
}

/** 记住：生成一把不可导出的钥匙，口令封好，钥匙和密文一起存。 */
export async function rememberPassword(password: string): Promise<void> {
  const key = await crypto.subtle.generateKey({ name: "AES-GCM", length: 256 }, false, ["encrypt", "decrypt"]);
  const iv = crypto.getRandomValues(new Uint8Array(12));
  const ct = await crypto.subtle.encrypt({ name: "AES-GCM", iv }, key, new TextEncoder().encode(password));
  const rec: Record_ = { key, iv, ct };
  await tx("readwrite", (s) => s.put(rec, KEY));
}

/** 记着的口令；没记 / 解不开（库被动过）→ null。 */
export async function recallPassword(): Promise<string | null> {
  const rec = await tx<Record_>("readonly", (s) => s.get(KEY) as IDBRequest<Record_>).catch(() => undefined);
  if (!rec) return null;
  try { return new TextDecoder().decode(await crypto.subtle.decrypt({ name: "AES-GCM", iv: rec.iv }, rec.key, rec.ct)); }
  catch { return null; }
}

export const hasRememberedPassword = async (): Promise<boolean> => (await tx<Record_>("readonly", (s) => s.get(KEY) as IDBRequest<Record_>).catch(() => undefined)) != null;

/** 忘记（删记录；钥匙跟着没了）。 */
export const forgetPassword = (): Promise<void> => tx("readwrite", (s) => s.delete(KEY)).then(() => undefined);
