import { createStore, createOneDriveProvider, requestStoragePersistence } from "@internal/store";
import type { Store, OneDriveAuth } from "@internal/store";
import { createEncryption } from "@internal/encryption";
import { APP_ID, CLIENT_ID, AUTHORITY, SCOPES, MSAL_URL, CRUMB_SUFFIX, JAM_SUFFIX } from "./config.ts";
import { storeUI } from "./store-ui.ts";
import { stagingCapBytes } from "./device-kv.ts";

const od = createOneDriveProvider({ clientId: CLIENT_ID, scopes: SCOPES, authority: AUTHORITY, msalUrl: MSAL_URL });
export const auth: OneDriveAuth = od.auth;

let activeIdentifier: string | null = null;
/** 正在玩的盘（云端去抖收敛绝不动它）。 */
export function setActiveIdentifier(id: string | null): void { activeIdentifier = id; }

/** 快照 / 存档 / 盘都是 KRD 容器（KRD2 头部 64 字节 / KRD1 尾部 64 字节，首尾魔数）；未加密的盘镜像不会经 open() 采纳（只流式读），这里只验 KRD。
 *  captive portal 的 200 HTML 之类永远不许盖掉本地唯一好副本。 */
async function validateAdopt(plain: Blob): Promise<boolean> {
  if (plain.size < 64) return false;
  const dec = new TextDecoder();
  const block = async (off: number) => new Uint8Array(await plain.slice(off, off + 64).arrayBuffer());
  const head = await block(0);
  if (dec.decode(head.subarray(0, 4)) === "KRD2" && dec.decode(head.subarray(60, 64)) === "KRD2") return true;
  const tail = await block(plain.size - 64);
  return dec.decode(tail.subarray(0, 4)) === "KRD1" && dec.decode(tail.subarray(60, 64)) === "KRD1";
}

let store: Store | null = null;
export function getStore(): Store {
  store ??= createStore({
    provider: od.provider,
    ui: storeUI,
    appId: APP_ID,
    persistence: "app-managed",         // 登录按钮的手势里调 requestStoragePersistence()
    encryption: createEncryption(),     // 不用库的加密（我们自己的 KRD1 在 app 层封好再交给库，库只见密文）
    reconcilePolicy: "app-driven",
    validateAdopt,
    docKinds: [
      { kind: "disc", suffix: ".wafter", container: "raw" },
      { kind: "disc", suffix: ".iso", container: "raw" },
      { kind: "disc", suffix: ".cso", container: "raw" },
      { kind: "crumb", suffix: CRUMB_SUFFIX, container: "raw" },
      { kind: "jam", suffix: JAM_SUFFIX, container: "raw" },
    ],
    autoCacheOpenedFile: true,          // 快照 / 存档 open 后留本地；盘只走 openStream（不整份落本地）
    ...(stagingCapBytes() ? { stagingCapBytes: stagingCapBytes() } : {}),   // 流式暂存区上限（设置里改；user「cache上限设置」）。改了要重新载入才生效
    offlineUploadReplay: "auto",
    signedIn: () => od.auth.isSignedIn(),
    activeIdentifier: () => activeIdentifier,
  });
  return store;
}

export { requestStoragePersistence };
export type { Store };
