// 屏幕软键 —— created 20261014 by Claude Opus 5.5
// user 10-14「ipad软键，暂停这些都是刚需」；Quest 上用射线点（user「用pointer玩galge反而没问题」）→ 全走 pointer 事件，触屏 / 鼠标 / 射线一样。
// 多指：每个 pointer 各自记着按在哪，合并成一个按键位图。手指按住滑到别的键上 = 换键（十字键按角度判 8 向，斜方向 = 两个键）。
// PSP 的 ○ × □ △ 先用 CSS 画的几何形顶位（不依赖字体）；图标库缺这四个和「手柄」，已登记 SVG Icons/TODO.md。
// 摇杆（W-13，user 10-14「psp软键盘为什么没有摇杆哈哈哈哈哈」edited by Claude Opus 5.5）：固定底座，按住拖 = 偏离中心的方向和距离（半径归一到 1），
//   松手回中；死区同手柄 0.12。和十字键分开：PSP 游戏有的只认摇杆（3D 移动），有的只认十字键。
import { bit, type ButtonName } from "./core-session.ts";
import { h } from "./ui.ts";

const FACE: [ButtonName, string][] = [["triangle", "tri"], ["square", "sq"], ["circle", "ci"], ["cross", "cr"]];

export interface SoftKeys {
  readonly el: HTMLElement;
  setVisible(v: boolean): void;
  readonly visible: boolean;
}

const STICK_DEADZONE = 0.12;

/** 软键回调：按键位图、两根摇杆、暂停（点一下切换）、快进（按住）。 */
export interface SoftKeyHandlers {
  onMask(mask: number): void;
  onLeftStick(x: number, y: number): void;
  /** 右摇杆（PSP 本机没有）：宿主决定映射到什么（现在 = 十字键）。 */
  onRightStick(x: number, y: number): void;
  onPause(): void;
  onFast(down: boolean): void;
}

// 布局照标准手柄做全（user 10-14「不是说双摇杆吗一开始肌肉记忆做全。然后lt rt也要，然后还有就是加速和暂停键盘上也有」）：
//   左：LT / L 在上，左摇杆在十字键上方；右：R / RT 在上，右摇杆在四键上方；中间一排：暂停 · SELECT · START · 快进（按住）。
//   LT / RT 和实体手柄一样当 L / R（宿主的 PAD_MAP 同一张表）。edited 20261014 by Claude Opus 5.5
export function mountSoftKeys(host: HTMLElement, on: SoftKeyHandlers): SoftKeys {
  const keys = new Map<string, { el: HTMLElement; bits: number }>();
  const key = (id: string, bits: number, cls: string, label: Node | string) => {
    const el = h("div", { class: `pk ${cls}`, "data-k": id }, label);
    keys.set(id, { el, bits });
    return el;
  };
  const dpad = h("div", { class: "dpad" },
    h("i", { class: "arm up" }), h("i", { class: "arm down" }), h("i", { class: "arm left" }), h("i", { class: "arm right" }));
  const face = h("div", { class: "face" }, ...FACE.map(([n, c]) => key(n, bit(n), `fb ${c}`, h("i", { class: `sym ${c}` }))));
  const mkStick = (side: "left" | "right") => { const knob = h("i", { class: "knob" }); return { el: h("div", { class: `stick ${side}` }, knob), knob }; };
  const sticks = { left: mkStick("left"), right: mkStick("right") };
  const pauseKey = h("div", { class: "pk small sys", "data-sys": "pause", title: "暂停 / 继续" }, "暂停");
  const fastKey = h("div", { class: "pk small sys", "data-sys": "fast", title: "按住快进" }, "快进");
  const layer = h("div", { class: "softkeys", hidden: true },
    key("lt", bit("l"), "shoulder lt", "LT"), key("l", bit("l"), "shoulder l", "L"),
    key("r", bit("r"), "shoulder r", "R"), key("rt", bit("r"), "shoulder rt", "RT"),
    sticks.left.el, dpad, sticks.right.el, face,
    h("div", { class: "mid" }, pauseKey, key("select", bit("select"), "small", "SELECT"), key("start", bit("start"), "small", "START"), fastKey));
  host.append(layer);

  const pointers = new Map<number, number>();
  let shown = 0;
  const publish = () => {
    let m = 0;
    for (const v of pointers.values()) m |= v;
    if (m === shown) return;
    shown = m;
    for (const [, k] of keys) k.el.classList.toggle("on", false);
    for (const [id, k] of keys) if ([...pointers.values()].some((v) => v === k.bits && pointerKey.get(id))) k.el.classList.add("on");
    for (const d of ["up", "down", "left", "right"] as const) dpad.querySelector(`.${d}`)!.classList.toggle("on", (m & bit(d)) !== 0);
    on.onMask(m);
  };
  // 哪些键现在被按着（高亮用；LT 和 L 给的是同一位，按 id 记才分得清亮哪个）
  const pointerKey = new Map<string, boolean>();
  const pointerOn = new Map<number, string | null>();

  const hit = (x: number, y: number): { bits: number; id: string | null } => {
    // 先认正落在哪个键上：十字键的判定区往外放了 15%，竖屏时它下面紧挨着中间一排，不能让放宽的边吃掉 SELECT
    for (const [id, k] of keys) {
      const b = k.el.getBoundingClientRect();
      if (x >= b.left && x <= b.right && y >= b.top && y <= b.bottom) return { bits: k.bits, id };
    }
    const r = dpad.getBoundingClientRect();
    const pad = r.width * 0.15;
    if (x >= r.left - pad && x <= r.right + pad && y >= r.top - pad && y <= r.bottom + pad) {
      const dx = x - (r.left + r.width / 2), dy = y - (r.top + r.height / 2);
      if (Math.hypot(dx, dy) < r.width * 0.12) return { bits: 0, id: null };
      const sector = (Math.round(Math.atan2(dy, dx) / (Math.PI / 4)) + 8) % 8; // 0 = 右，顺时针（屏幕坐标 y 向下）
      return { bits: [bit("right"), bit("right") | bit("down"), bit("down"), bit("down") | bit("left"),
        bit("left"), bit("left") | bit("up"), bit("up"), bit("up") | bit("right")][sector], id: null };
    }
    for (const [id, k] of keys) {
      const b = k.el.getBoundingClientRect();
      if (x >= b.left - 4 && x <= b.right + 4 && y >= b.top - 4 && y <= b.bottom + 4) return { bits: k.bits, id };
    }
    return { bits: 0, id: null };
  };
  const setPointer = (pid: number, x: number, y: number) => {
    const prev = pointerOn.get(pid);
    if (prev) pointerKey.set(prev, false);
    const got = hit(x, y);
    pointers.set(pid, got.bits);
    pointerOn.set(pid, got.id);
    if (got.id) pointerKey.set(got.id, true);
    shown = -1; // 高亮跟着 id 走：位图一样也重画
    publish();
  };

  // 摇杆：每根一次只认一根手指（先按住的那根）
  const stickPointer: Record<"left" | "right", number | null> = { left: null, right: null };
  const stickMove = (side: "left" | "right", x: number, y: number) => {
    const s = sticks[side];
    const r = s.el.getBoundingClientRect();
    const rad = r.width / 2;
    let dx = (x - (r.left + rad)) / rad, dy = (y - (r.top + rad)) / rad;
    const len = Math.hypot(dx, dy);
    if (len > 1) { dx /= len; dy /= len; }
    s.knob.style.transform = `translate(${(dx * 50).toFixed(1)}%, ${(dy * 50).toFixed(1)}%)`;
    s.el.classList.add("on");
    const dead = Math.hypot(dx, dy) < STICK_DEADZONE;
    (side === "left" ? on.onLeftStick : on.onRightStick)(dead ? 0 : dx, dead ? 0 : dy);
  };
  const stickRelease = (side: "left" | "right") => {
    stickPointer[side] = null;
    sticks[side].knob.style.transform = "";
    sticks[side].el.classList.remove("on");
    (side === "left" ? on.onLeftStick : on.onRightStick)(0, 0);
  };
  const sideOf = (pid: number): "left" | "right" | null => (stickPointer.left === pid ? "left" : stickPointer.right === pid ? "right" : null);
  let fastPointer: number | null = null;

  layer.addEventListener("pointerdown", (e) => {
    const t = e.target as HTMLElement;
    const st = t.closest(".stick") as HTMLElement | null;
    if (st) {
      const side = st.classList.contains("right") ? "right" : "left";
      if (stickPointer[side] !== null) return;
      e.preventDefault();
      layer.setPointerCapture(e.pointerId);
      stickPointer[side] = e.pointerId;
      stickMove(side, e.clientX, e.clientY);
      return;
    }
    const sys = (t.closest("[data-sys]") as HTMLElement | null)?.dataset.sys;
    if (sys === "pause") { e.preventDefault(); on.onPause(); return; }
    if (sys === "fast") { e.preventDefault(); layer.setPointerCapture(e.pointerId); fastPointer = e.pointerId; fastKey.classList.add("on"); on.onFast(true); return; }
    if (!t.closest(".pk, .dpad")) return;
    e.preventDefault();
    layer.setPointerCapture(e.pointerId);
    setPointer(e.pointerId, e.clientX, e.clientY);
  });
  layer.addEventListener("pointermove", (e) => {
    const side = sideOf(e.pointerId);
    if (side) { stickMove(side, e.clientX, e.clientY); return; }
    if (!pointers.has(e.pointerId)) return;
    setPointer(e.pointerId, e.clientX, e.clientY);
  });
  const release = (e: PointerEvent) => {
    const side = sideOf(e.pointerId);
    if (side) { stickRelease(side); return; }
    if (e.pointerId === fastPointer) { fastPointer = null; fastKey.classList.remove("on"); on.onFast(false); return; }
    const id = pointerOn.get(e.pointerId);
    if (id) pointerKey.set(id, false);
    pointerOn.delete(e.pointerId);
    if (pointers.delete(e.pointerId)) { shown = -1; publish(); }
  };
  layer.addEventListener("pointerup", release);
  layer.addEventListener("pointercancel", release);
  layer.addEventListener("lostpointercapture", release);
  layer.addEventListener("contextmenu", (e) => e.preventDefault());

  return {
    el: layer,
    setVisible(v) {
      layer.hidden = !v;
      if (!v) {
        pointers.clear(); pointerOn.clear(); pointerKey.clear(); shown = -1; publish();
        for (const side of ["left", "right"] as const) if (stickPointer[side] !== null) stickRelease(side);
        if (fastPointer !== null) { fastPointer = null; fastKey.classList.remove("on"); on.onFast(false); }
      }
    },
    get visible() { return !layer.hidden; },
  };
}
