        //   TypeError 必是网络层；上层泛判 instanceof TypeError 会把自家 bug 误装成「网络问题」，禁止。
        let response;
        try {
            response = await fetch(url, init);
        }
        catch (e) {
            throw new CloudNetworkError(`Graph ${method} ${pathOrUrl}: network fetch failed (${String(e)})`, e);
        }
        if (!response.ok) {
            let detail = "";
            try {
                detail = await response.text();
            }
            catch (_) { }
            const err = new Error(`Graph ${method} ${pathOrUrl} → ${response.status}: ${detail}`);
            err.status = response.status;
            err.body = detail;
            throw err;
        }
        return response;
