export function createFreshHints(opts = {}) {
    const ttl = opts.ttlMs ?? 30_000;
    const now = opts.now ?? (() => Date.now());
    const map = new Map();
    return {
        note(name, meta) { map.set(name, { meta, at: now() }); },
        peek(name) {
            const h = map.get(name);
            if (!h)
                return null;
            if (now() - h.at > ttl) {
                map.delete(name);
                return null;
            }
            return h.meta;
        },
        forget(name) { map.delete(name); },
    };
}
