// PC 版 PPSSPP 快照（.ppst）的文件头：拆 / 拼（纯函数，零依赖）—— created 20261014 by Claude Opus 5.5（W-7 回本机 PPSSPP 的逃生口，快照那一半）
// 格式 = 上游 Common/Serialize/Serializer.{h,cpp}（v1.20.4 核过）：小端
//   0 Revision i32（≥ 4；≥ 5 才有标题）· 4 Compress i32（0 = 不压 / 1 = snappy / 2 = zstd）· 8 ExpectedSize u32（头后面的字节数）
//   12 UncompressedSize u32 · 16 GitVersion char[32] · [48 Title char[128]（Revision ≥ 5）] · 正文
// 正文解压后 = libretro retro_serialize 的字节（两边是同一个 SaveState::SaveStart 类；libretro 版把长度补齐到 8 MB 的倍数，读的时候不检查尾巴）。
// 10-14 实测：PC 上 v1.19.3 存的库特快照解开后，wasm 核（v1.20.4）读得进去、接着跑。
export const PPST_REVISION = 5;
export const PPST_COMPRESS = { none: 0, snappy: 1, zstd: 2 } as const;
const HEAD = 48, TITLE = 128;

export interface PpstFile { revision: number; compress: number; gitVersion: string; title: string; uncompressedSize: number; body: Uint8Array }

const cstr = (b: Uint8Array) => { const end = b.indexOf(0); return new TextDecoder().decode(end < 0 ? b : b.subarray(0, end)); };

export function parsePpst(bytes: Uint8Array): PpstFile {
  if (bytes.length < HEAD) throw new Error("not a PPSSPP savestate (too small)");
  const dv = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
  const revision = dv.getInt32(0, true), compress = dv.getInt32(4, true), expected = dv.getUint32(8, true), uncompressedSize = dv.getUint32(12, true);
  if (revision < 4 || revision > 64) throw new Error(`not a PPSSPP savestate (revision ${revision})`);
  const head = HEAD + (revision >= 5 ? TITLE : 0);
  if (head + expected !== bytes.length) throw new Error(`PPSSPP savestate size mismatch: header says ${expected}, file has ${bytes.length - head}`);
  return {
    revision, compress, uncompressedSize,
    gitVersion: cstr(bytes.subarray(16, 48)),
    title: revision >= 5 ? cstr(bytes.subarray(48, 48 + TITLE)) : "",
    body: bytes.subarray(head),
  };
}

/** 拼一个不压缩的 .ppst（PPSSPP 读的时候认 Compress = 0）。 */
export function buildPpst(payload: Uint8Array, opts: { title: string; gitVersion: string }): Uint8Array {
  const out = new Uint8Array(HEAD + TITLE + payload.length);
  const dv = new DataView(out.buffer);
  dv.setInt32(0, PPST_REVISION, true);
  dv.setInt32(4, PPST_COMPRESS.none, true);
  dv.setUint32(8, payload.length, true);
  dv.setUint32(12, payload.length, true);
  const enc = new TextEncoder();
  out.set(enc.encode(opts.gitVersion).subarray(0, 31), 16);
  out.set(enc.encode(opts.title).subarray(0, TITLE - 1), HEAD);
  out.set(payload, HEAD + TITLE);
  return out;
}

/** PPSSPP 的快照文件名：<盘号>_<版本>_<格>.ppst（盘号 / 版本可能是空的：LUCK03554__0）。 */
export function parsePpstName(name: string): { id: string; version: string; slot: number } | null {
  const m = /^([A-Z0-9]+)_([0-9.]*)_(\d+)\.ppst$/i.exec(name.replace(/^.*[\\/]/, ""));
  return m ? { id: m[1], version: m[2], slot: Number(m[3]) } : null;
}
