// 给一个 Promise 加期限：到点了先返回 "timeout" 让调用方放手，原 Promise 照跑 —— created 20261015 by Claude Fable 5.1
// 用处：iOS 锁屏 / 切后台时在途的 fetch 回来后常常既不成功也不报错、永远挂着（10-15 user「锁屏之后总是自动存档，多锁几次，全卡死了，手动存档都不行了」）。
//   存快照 / 存档罐的「正在存」锁不能跟着一个永远不结束的上传一起挂死：本机那份早就落下了，上传交给续推。
export function withDeadline<T>(p: Promise<T>, ms: number, onSettleLate?: (r: { ok: true; value: T } | { ok: false; error: unknown }) => void): Promise<T | "timeout"> {
  let timedOut = false;
  let timer = 0;
  const late = p.then((value) => { if (timedOut) onSettleLate?.({ ok: true, value }); return value; }, (error: unknown) => { if (timedOut) onSettleLate?.({ ok: false, error }); throw error; });
  return Promise.race([
    late.finally(() => clearTimeout(timer)),
    new Promise<"timeout">((resolve) => { timer = window.setTimeout(() => { timedOut = true; resolve("timeout"); }, ms); }),
  ]);
}
