// 面板：存档管理、回收站 / 备份箱、重复的存档罐、同步日志 —— created 20261014 by Claude Fable 5.1
// 「删除 = 移到回收站，可恢复」「冲突输的一方进备份箱」只有在人能打开那个箱子的时候才算数；本 app 不用 gallery，所以自己画。
import { sheet, h, banner, note, errorText, withBusy } from "./ui.ts";
import { listBins, restoreBin, deleteJam, renameJam, listFolderOnce, nudge, needsAttention, peekMeta, parseCrumbId, SYNC_TEXT, jarFolder, type BinItem, type FolderItem } from "./saves.ts";
import { labelFor } from "./labels.ts";
import { CRUMBS, PLATFORM_CODE } from "./config.ts";
import { dumpLog } from "./sync-status.ts";
import type { DiscMeta } from "../disc/crypt.ts";

const fmtTs = (ts: string | null): string => (ts && ts.length >= 12 ? `${ts.slice(0, 4)}-${ts.slice(4, 6)}-${ts.slice(6, 8)} ${ts.slice(8, 10)}:${ts.slice(10, 12)}` : "");
const fmtWhen = (t?: number) => (t ? new Date(t).toLocaleString() : "");
const fmtSize = (n?: number) => (n ? (n >= 2 ** 20 ? `${(n / 2 ** 20).toFixed(1)} MB` : `${(n / 1024).toFixed(0)} KB`) : "");
const sideText = { local: "只在这台设备", cloud: "只在云端", both: "两边都有" } as const;

/** 回收站 + 备份箱，一个面板。恢复撞名时库自己给主干加时间戳，不覆盖现有的。 */
export async function openBins(): Promise<void> {
  let items: BinItem[];
  try { items = await withBusy("正在列回收站…", listBins); } catch (e) { banner(`列不出回收站：${errorText(e)}`); return; }
  await sheet<void>((done) => {
    const row = (it: BinItem) => h("div", { class: "bin-row" },
      h("div", { class: "slot-text" },
        h("span", { class: "slot-name" }, it.label),
        h("span", { class: "muted" }, `${it.bin === "trash" ? "回收站" : "备份箱"} · ${fmtTs(it.ts)} · ${sideText[it.side]}`)),
      h("button", { onclick: async () => {
        done();
        try {
          const status = await restoreBin(it);
          banner(`已恢复（${status}）。恢复出来的和现有的同名时，文件名会多一个时间戳；存档罐重复时下次开盘会让你选一罐。`, "warning");
        } catch (e) { banner(`恢复失败：${errorText(e)}`); }
      } }, "恢复"));
    return [
      h("h2", {}, "回收站 / 备份箱"),
      h("p", { class: "hint" }, "删掉的快照、程序自己删掉的存档在回收站；云端和这台设备冲突时输的那一方在备份箱。都没有真的丢。"),
      items.length ? h("div", { class: "bins" }, ...items.map(row)) : h("p", { class: "muted" }, "是空的。"),
      h("div", { class: "row" }, h("button", { onclick: () => done() }, "关闭")),
    ];
  });
}

/** 存档管理要认游戏，壳给它的本事：口令（没有 = 只能显示泛称）、按游戏身份代号 / 存档目录名找盘名（主页「输入口令」时读的名片表）。 */
export interface SaveManagerContext {
  password(): string | null;
  askPassword(): Promise<string | null>;
  titleByKey(key: string): string | null;
  titleByDir(dir: string): string | null;
  /** 只看一张盘的（点盘四选一里的「存档管理」）：快照按游戏身份代号过滤；存档罐按目录名开头 = 盘号（读了元数据才知道，没口令时全显示）。 */
  only?: { title: string; key: string; discId?: string };
  /** 正在玩的那张盘：它的快照能直接「读」。 */
  loadSnapshot?: { key: string; load(id: string, kind: "s" | "a", n: number): void };
}

interface Row { it: FolderItem; meta: DiscMeta | null; peeked: boolean }

/** 一条属于哪个游戏（分组用）：快照 = 元数据盘名 / 代号对名片 / 盘号；罐 = 目录名开头的盘号对名片。认不出 = 「别的」。 */
function gameOf(r: Row, ctx: SaveManagerContext): string {
  const c = parseCrumbId(r.it.identifier);
  if (c) return r.meta?.t ?? ctx.titleByKey(c.key) ?? (r.meta?.fp?.id ? `${r.meta.fp.id}${r.meta.fp.v ? ` v${r.meta.fp.v}` : ""}` : `代号 ${c.key.slice(0, 8)}…`);
  const dir = r.meta?.jar?.u;
  if (dir) return ctx.titleByDir(dir) ?? dir.slice(0, 9);
  return r.peeked ? "别的" : "…";
}
function nameOf(r: Row): string {
  const c = parseCrumbId(r.it.identifier);
  if (c) return `快照 ${c.kind === "s" ? "手动" : "自动"} ${c.n}`;
  const dir = r.meta?.jar?.u;
  return dir ? `存档 ${dir}` : labelFor(r.it.identifier);
}
/** 时间：元数据里记的存档时刻（最重要的一项，user 10-14「但最重要的是时间」）；老文件退回文件时间并标明。 */
const whenOf = (r: Row): number => r.meta?.at ?? r.it.lastModified ?? 0;
const whenText = (r: Row): string => (r.meta?.at ? fmtWhen(r.meta.at) : r.it.lastModified ? `${fmtWhen(r.it.lastModified)}（文件时间）` : "时间不明");

/** 存档管理：按游戏分组、时间倒序、带缩略图；要处理的（没传 / 冲突 / 云端新版）单列在最上面。
 *  处理 = 推一把（库走 If-Match / 冲突面）/ 拉云端 / 删（回收站）；正在玩的盘的快照能直接读。名字和时间逐条读元数据补上（4 路并发，边读边刷）。
 *  user 10-14「还是需要一个存档管理界面」「存档管理似乎需要能看见是哪个游戏」「点开之后是存档管理界面，做好一点」。 */
export async function openSaveManager(ctx: SaveManagerContext): Promise<void> {
  let jars: FolderItem[], crumbs: FolderItem[], complete: boolean;
  try {
    const [j, c] = await withBusy("正在列存档…", () => Promise.all([listFolderOnce(jarFolder(PLATFORM_CODE.psp), 8000), listFolderOnce(CRUMBS, 8000)]));
    jars = j.items; crumbs = c.items; complete = j.complete && c.complete;
  } catch (e) { banner(`列不出存档：${errorText(e)}`); return; }
  const only = ctx.only;
  const rows: Row[] = [...jars, ...crumbs]
    .filter((it) => { const c = parseCrumbId(it.identifier); return !only || !c || c.key === only.key; }) // 快照按代号先筛；罐要读了元数据才知道
    .map((it) => ({ it, meta: null, peeked: false }));
  let cancelled = false, peeking = 0;
  const body = h("div", { class: "sm-body" });
  let closeSheet: () => void = () => {};

  const render = () => {
    const visible = rows.filter((r) => !(only && r.meta?.jar && !(only.discId && r.meta.jar.u.toUpperCase().startsWith(only.discId.toUpperCase()))));
    const todo = visible.filter((r) => needsAttention(r.it.syncState)).sort((a, b) => whenOf(b) - whenOf(a));
    const groups = new Map<string, Row[]>();
    for (const r of visible) groups.set(gameOf(r, ctx), [...(groups.get(gameOf(r, ctx)) ?? []), r]);
    const sections = [...groups].map(([g, rs]) => [g, rs.sort((a, b) => whenOf(b) - whenOf(a))] as const).sort((a, b) => whenOf(b[1][0]) - whenOf(a[1][0]));
    body.replaceChildren(
      h("h3", {}, todo.length ? `要处理的（${todo.length}）` : "没有要处理的"),
      ...(todo.length ? [h("div", { class: "bins" }, ...todo.map((r) => row(r, true)))] : []),
      ...(peeking ? [h("p", { class: "muted" }, `正在读名字和时间…（还有 ${peeking} 条）`)] : []),
      ...sections.flatMap(([g, rs]) => [h("h3", {}, `${g}（${rs.length}）`), h("div", { class: "bins" }, ...rs.map((r) => row(r, false)))]),
      ...(visible.length ? [] : [h("p", { class: "muted" }, "空的。")]),
    );
  };
  const row = (r: Row, inTodo: boolean) => {
    const c = parseCrumbId(r.it.identifier);
    const thumb = c ? h("div", { class: "thumb small" }, r.meta?.thumb ? h("img", { src: `data:image/jpeg;base64,${r.meta.thumb}`, alt: "" }) : null) : null;
    const canLoad = c && ctx.loadSnapshot && c.key === ctx.loadSnapshot.key && r.it.syncState !== "cloud-only" ? ctx.loadSnapshot : null;
    return h("div", { class: `bin-row${needsAttention(r.it.syncState) ? " attention" : ""}` },
      thumb,
      h("div", { class: "slot-text" },
        h("span", { class: "slot-name" }, inTodo ? `${nameOf(r)} · ${gameOf(r, ctx)}` : nameOf(r)),
        h("span", { class: "muted" }, [whenText(r), SYNC_TEXT[r.it.syncState] ?? r.it.syncState, fmtSize(r.it.size)].filter(Boolean).join(" · "))),
      needsAttention(r.it.syncState) ? h("button", { class: "primary", onclick: async () => {
        closeSheet();
        try { note(await nudge(r.it.identifier, r.it.syncState), 6000); } catch (e) { banner(`没处理成：${errorText(e)}`); }
      } }, r.it.syncState === "newer-on-cloud" ? "拉云端的" : "推一把") : null,
      canLoad ? h("button", { class: "primary", onclick: () => { closeSheet(); canLoad.load(r.it.identifier, c!.kind, c!.n); } }, "读") : null,
      h("button", { title: "移到回收站", onclick: async () => {
        closeSheet();
        try { if (await deleteJam(r.it.identifier)) note("已移到回收站"); } catch (e) { banner(`没能移到回收站：${errorText(e)}`); }
      } }, "删"));
  };
  const fill = async () => {
    const pw = ctx.password();
    if (!pw) return;
    const queue = rows.filter((r) => !r.peeked);
    peeking = queue.length;
    render();
    let dirty = false;
    const flush = () => { if (dirty && !cancelled) { dirty = false; render(); } };
    const ticker = setInterval(flush, 400); // 别每条都重画整个面板
    const worker = async () => {
      while (queue.length && !cancelled) {
        const r = queue.shift()!;
        r.meta = await peekMeta(r.it.identifier, pw).catch(() => null);
        r.peeked = true;
        peeking--;
        dirty = true;
      }
    };
    await Promise.all(Array.from({ length: 4 }, worker));
    clearInterval(ticker);
    flush();
  };
  render();
  void fill();
  await sheet<void>((done) => {
    closeSheet = () => done();
    const unlock = ctx.password() ? null : h("button", { onclick: async () => { if (await ctx.askPassword()) { unlock!.remove(); void fill(); } } }, "输入口令，看是哪张盘的");
    return [
      h("h2", {}, only ? `存档管理 · ${only.title}` : "存档管理"),
      h("p", { class: "hint" }, `${complete ? "" : "云端列表没拿全（没登录 / 网络慢），看到的可能不全。"}「推一把」= 把这台的那份再传一次：云端也改过就会让你选，输的进备份箱。`),
      unlock,
      body,
      h("div", { class: "row" },
        h("button", { onclick: () => { done(); openBins().catch((e) => banner(errorText(e))); } }, "回收站 / 备份箱"),
        h("button", { onclick: () => { done(); openLog(); } }, "同步日志"),
        h("button", { onclick: () => done() }, "关闭")),
    ].filter(Boolean) as Node[];
  }).finally(() => { cancelled = true; });
}

/** 黑匣子：这一页的上传 / 冲突 / 出错记录（内存里最近几百条），能复制。 */
export function openLog(): void {
  const text = dumpLog();
  void sheet<void>((done) => [
    h("h2", {}, "同步日志（这一页）"),
    h("pre", { class: "log" }, text),
    h("div", { class: "row" },
      h("button", { onclick: () => { navigator.clipboard?.writeText(text).then(() => note("已复制"), () => note("复制不了，手动选中复制")); } }, "复制"),
      h("button", { onclick: () => done() }, "关闭")),
  ]);
}

/** 同一个存档目录装在不止一罐里：人选一罐留下，其余进回收站；留下的不是标准名（回收站恢复出来的 `… [时间戳].jam`）就改回标准名——
 *  不然游戏下次一存又写标准名、又成重复（Opus 10-14 读码指出）。什么都不选 = 这一局这个目录不读也不写。返回是否有改动（改了要重新开盘才生效）。 */
export async function resolveDuplicates(duplicates: Map<string, string[]>, peek: (id: string) => Promise<{ at?: number; size?: number } | null>,
  standardId: (dir: string) => Promise<string>): Promise<boolean> {
  let changed = false;
  for (const [dir, ids] of duplicates) {
    const infos = await Promise.all(ids.map(async (id) => ({ id, meta: await peek(id).catch(() => null) })));
    const keep = await sheet<string>((done) => [
      h("h2", {}, `存档「${dir}」有 ${ids.length} 份`),
      h("p", { class: "hint" }, "可能是从回收站恢复过、或手工搬过存档。选一份留下，其余移到回收站；不选 = 这次这个存档不读也不写。"),
      h("div", { class: "bins" }, ...infos.map(({ id, meta }) => h("div", { class: "bin-row" },
        h("div", { class: "slot-text" },
          h("span", { class: "slot-name" }, labelFor(id)),
          h("span", { class: "muted" }, [meta?.at ? fmtWhen(meta.at) : "时间不明", `${id.replace(/^.*\//, "").slice(0, 8)}…`, meta?.size ? `${(meta.size / 1024).toFixed(0)} KB` : ""].filter(Boolean).join(" · "))),
        h("button", { class: "primary", onclick: () => done(id) }, "留这份")))),
      h("div", { class: "row" }, h("button", { onclick: () => done(null) }, "先不选")),
    ], { dismissable: false });
    if (!keep) continue;
    for (const id of ids) {
      if (id === keep) continue;
      try { if (await deleteJam(id)) changed = true; } catch (e) { banner(`没能移到回收站：${errorText(e)}`); }
    }
    const std = await standardId(dir);
    if (keep !== std) {
      try { if (await renameJam(keep, std)) changed = true; else banner(`「${dir}」留下的那罐没能改回标准名（目标还被占着）：下次开盘可能还要再选一次。`, "warning"); }
      catch (e) { banner(`改名失败：${errorText(e)}`); }
    }
  }
  return changed;
}
