// 给 @internal/store 的 ui 回调 —— created 20261014 by Claude Opus 5.5
// 三个都是真的（库要求：禁空实现）：busy = 全屏遮罩（后台节律只走状态提示）；冲突 = 三选一面板，绝不静默；报错 = 横条。
// 本 app 不用 gallery（user 10-14「存档管理归app，rom管理归windows」），这几样自己画。
import type { StoreUI } from "@internal/store";
import { withBusy, sheet, h, banner, note, errorText, isNetworkError } from "./ui.ts";
import { labelFor } from "./labels.ts";
import { logEvent, networkHiccup } from "./sync-status.ts";

// 不罩全屏的：上传盘能传几分钟（状态条画进度）；新鲜度检查 / 拉取（读盘、接谱系、推完复核都会走）——游戏不能停，而且 iOS 锁屏后这类请求
//   可能永远不结束，罩上去 = 整页卡死（10-15 user「多锁几次，全卡死了」）。拉取给一行提示。
const BACKGROUND_KEYS = new Set(["sync.pushing", "file.renaming", "file.uploading", "cloud.checking", "file.pulling"]);

const stemOf = (identifier: string): string => labelFor(identifier);

export const storeUI: StoreUI = {
  busy: (label, fn, key) => {
    if (!key || !BACKGROUND_KEYS.has(key)) return withBusy(label, fn);
    if (key === "file.pulling") note(label, 30_000);
    return fn();
  },
  resolveConflict: async ({ name, occasion }) => {
    const choice = await sheet<"keepMine" | "takeCloud" | "cancel">((done) => [
      h("h2", {}, "云端和这台设备上的不一样"),
      h("p", {}, `${stemOf(name)}：云端那份和这台设备上要存的这份不是同一个版本（别的设备存过，或者这台没读到过云端那份）。`),
      h("p", { class: "hint" }, occasion === "push"
        ? "「用这台的」= 用这台的覆盖云端，云端那份移到备份箱；「用云端的」= 这台的移到备份箱，换成云端那份。两边都不会丢，备份箱里能找回。"
        : "现在先打开这台设备上的；「用云端的」= 这台的移到备份箱，换成云端那份。"),
      h("div", { class: "row" },
        h("button", { onclick: () => done("cancel") }, "先不管"),
        h("button", { onclick: () => done("takeCloud") }, "用云端的"),
        h("button", { class: "primary", onclick: () => done("keepMine") }, "用这台的")),
    ], { dismissable: false });
    logEvent("warn", `冲突：${stemOf(name)}（${occasion}）→ ${{ keepMine: "用这台的", takeCloud: "用云端的", cancel: "先不管" }[choice ?? "cancel"]}`);
    return choice ?? "cancel";
  },
  reportError: (err, level = "error") => {
    // 没登录时库的后台云动作会报 "Not signed in"：那是正常态，不上横条
    if ((err as { message?: string } | null)?.message === "Not signed in") { console.info("[store]", err); return; }
    if (level === "log") { console.info("[store]", err); return; }
    if (level === "info") { note(errorText(err)); return; }
    // 网络抖一下（10-14 user iPad 截图：上传快照第二块 Load failed → 英文红横条盖在游戏上）：字节在本机、会自动再传 →
    //   不弹横条，状态条变黄说清楚，原文进黑匣子日志
    if (isNetworkError(err)) { networkHiccup(String((err as { message?: string })?.message ?? err)); return; }
    logEvent(level === "warning" ? "warn" : "error", `store：${errorText(err)}`);
    banner(errorText(err), level);
  },
  onReplayStatus: ({ phase, name, done, total }) => {
    if (phase === "collision") banner(`${name ? stemOf(name) : ""}：云端已经有同名的了，离线时存的这份没传上去`, "warning");
    else if (phase === "done") note(`离线时存的传上云了（${done} / ${total}）`);
    else if (phase === "pushed") note(`正在把离线时存的传上云… ${done} / ${total}`);
  },
};
