// 一局游戏 = 一个 wasm 核实例 —— created 20261014 by Claude Opus 5.5（从 M2 点亮页 web/app.js 搬来）
// 主线程只做：替核读盘（按需、异步）、软件渲染兜底时画画面、把按键写进共享内存、起声音（AudioWorklet 直接读核的共享内存）、转达快照 / 暂停 / 快进。
// 核本身跑在 pthread 里（core/ppsspp/host.c）。一页只起一个核（固定 768 MB 共享内存）：换盘 = 重新载入页面。

/** 核按需读盘用的数据源（读出来就是明文）。 */
export interface DiscMedia {
  readonly size: number;
  read(offset: number, length: number): Promise<Uint8Array>;
}

// emscripten 导出的东西（只列用到的）
interface KrCore {
  HEAPU8: Uint8Array; HEAP32: Int32Array; HEAPF64: Float64Array;
  FS: EmFS;
  _malloc(n: number): number; _free(p: number): void;
  [fn: `_kr_${string}`]: (...args: number[]) => number;
}
export interface EmFS {
  mkdirTree(path: string): void;
  writeFile(path: string, data: Uint8Array): void;
  readFile(path: string): Uint8Array;
  readdir(path: string): string[];
  stat(path: string): { mode: number; size: number; mtime: Date };
  utime(path: string, atime: number, mtime: number): void;
  isDir(mode: number): boolean;
  analyzePath(path: string): { exists: boolean };
}

// libretro joypad 位（PSP：○ = A、× = B、□ = Y、△ = X）
export const BUTTON = { cross: 0, square: 1, select: 2, start: 3, up: 4, down: 5, left: 6, right: 7, circle: 8, triangle: 9, l: 10, r: 11 } as const;
export type ButtonName = keyof typeof BUTTON;
export const bit = (b: ButtonName): number => 1 << BUTTON[b];

export const PACE_MODES = { wall: 0, audio: 1, vsync: 2 } as const;

export interface StartOptions {
  media: DiscMedia;
  /** 盘镜像的扩展名（.iso / .cso / .pbp …），PPSSPP 按它认格式。 */
  ext: string;
  coreDir: string;
  glCanvas: HTMLCanvasElement;
  softCanvas: HTMLCanvasElement;
  audioContext: AudioContext;
  lowLatency: boolean;
  pacing?: keyof typeof PACE_MODES;
  /** 核启动前放进记忆棒的文件（相对 /saves/PSP/SAVEDATA/）。 */
  memstick?: Map<string, Uint8Array>;
  /** 每个存档目录的存档时刻（epoch ms）：写进核的文件系统后把文件时间设回去，游戏里看到的存档时间才是真的（不然全是开盘那一刻）。 */
  memstickTimes?: Map<string, number>;
  /** 有输入（任意来源按下一个键 / 摇杆推出死区）：挂机判定用。 */
  onInput?: () => void;
}

export const MEMSTICK_DIR = "/saves/PSP/SAVEDATA";

// 存 / 读前要等核出过几帧：出了第一帧 = 模拟线程已经过了「已请求启动」进了运行循环（上游 EmuThreadPause 撞到 START_REQUESTED 直接返回 = 卡死）。
//   原来 60 帧（≈ 1 s @60fps；开场视频 / 无头环境只有十几 fps 时要 3–4 s）；10-15 冷启动改 2，探针 private/tests/resume-early.ts + state-cycle.ts 验过。
const RUNNING_FRAMES = 2;
export class CoreSession {
  readonly core: KrCore;
  private ac: AudioContext;
  private masks = new Map<string, number>(); // 各输入来源（键盘 / 手柄 / 软键）各自的按键位，合并后给核
  private paceBuf = 0;
  private mediaReads = 0;
  private hwChecked = false;
  private lastSeq = -1;
  private image: ImageData | null = null;
  private ctx2d: CanvasRenderingContext2D;
  private fpsWindow = { t: performance.now(), frames: 0, fps: 0, emuMs: 0, speed: 0 };
  // 读盘的网络用量：这一秒拿了多少字节、核等读盘等了多少毫秒（核的读是同步的——等多久就停多久，声音跟着欠）。
  //   user 10-14「状态栏显示实时网络用量判断是游戏卡了还是在等网」。added 20261014 by Claude Fable 5.1
  private net = { bytes: 0, waitMs: 0, inflight: 0, bps: 0, waitPerSec: 0 };
  private pace = { mean: 0, sd: 0, max: 0, late: 0, bunched: 0, frameMs: 0, frameMsSd: 0 };
  private perRefresh = { last: performance.now(), seq: 0, dts: [] as number[], counts: [0, 0, 0], hz: 0, shown: [0, 0, 0] };
  private startedAt = performance.now();

  private constructor(core: KrCore, private opts: StartOptions) {
    this.core = core;
    this.ac = opts.audioContext;
    this.ctx2d = opts.softCanvas.getContext("2d")!;
  }

  static async start(opts: StartOptions): Promise<CoreSession> {
    // 绝对地址：动态 import 的相对路径按 bundle 自己的位置解析，会指错目录
    const { default: createKrCore } = await import(new URL(`${opts.coreDir}kr-core.mjs`, location.href).href);
    let session: CoreSession | null = null;
    const media = opts.media;
    const core: KrCore = await createKrCore({
      krMedia: {
        size: media.size,
        read: async (offset: number, length: number) => {
          const s = session, t0 = performance.now();
          if (s) { s.mediaReads++; s.net.inflight++; }
          try {
            const bytes = await media.read(offset, length);
            if (s) s.net.bytes += bytes.length;
            return bytes;
          } finally {
            if (s) { s.net.waitMs += performance.now() - t0; s.net.inflight--; }
          }
        },
      },
      arguments: [`/disc/game${opts.ext}`, String(media.size), ...(opts.lowLatency ? ["lowlatency"] : [])],
      locateFile: (path: string) => new URL(`${opts.coreDir}${path}`, location.href).href,
      preRun: [(M: KrCore) => {
        if (!opts.memstick?.size) return;
        for (const [rel, bytes] of opts.memstick) {
          const full = `${MEMSTICK_DIR}/${rel}`;
          M.FS.mkdirTree(full.replace(/\/[^/]*$/, ""));
          M.FS.writeFile(full, bytes);
          const at = opts.memstickTimes?.get(rel.split("/")[0]);
          if (at) { try { M.FS.utime(full, at, at); } catch (e) { console.warn("[memstick] utime", rel, e); } }
        }
      }],
      print: (s: string) => console.log(s),
      printErr: (s: string) => console.warn(s),
    });
    session = new CoreSession(core, opts);
    session.init();
    await session.startAudio();
    return session;
  }

  private init(): void {
    const { core, opts } = this;
    if (opts.pacing) core._kr_set_pacing(PACE_MODES[opts.pacing]);
    this.paceBuf = core._malloc(8 * 8);
    // 画布的实际显示像素告诉核（核在 GPU 里按整数倍放大）
    const tellSize = () => {
      const r = opts.glCanvas.getBoundingClientRect(), dpr = devicePixelRatio || 1;
      core._kr_set_display_size(Math.round(r.width * dpr), Math.round(r.height * dpr));
    };
    new ResizeObserver(tellSize).observe(opts.glCanvas);
    tellSize();
  }

  private async startAudio(): Promise<void> {
    const { core, ac } = this;
    await ac.audioWorklet.addModule(new URL("./audio-worklet.js", location.href));
    const node = new AudioWorkletNode(ac, "kr-audio", {
      numberOfInputs: 0,
      outputChannelCount: [2],
      processorOptions: {
        buffer: core.HEAPU8.buffer,
        ringPtr: core._kr_audio_ring(),
        ringFrames: core._kr_audio_ring_frames(),
        wPtr: core._kr_audio_w_ptr(),
        rPtr: core._kr_audio_r_ptr(),
        underrunPtr: core._kr_audio_underrun_ptr(),
        coreRate: core._kr_audio_rate(),
        targetFrames: 2048, // ≈ 46 ms；对齐模式下核那边的硬上限是 3584（≈ 81 ms）
      },
    });
    this.gain = ac.createGain();
    node.connect(this.gain).connect(ac.destination);
    this.applyGain();
    const sync = () => core._kr_audio_set_live(ac.state === "running" ? 1 : 0);
    ac.onstatechange = sync;
    // 浏览器没放行自动播放时，等下一次点击 / 按键再恢复（暂停中不恢复）；从后台回来（iOS 会把声音打成 interrupted）也试一次
    const resume = () => { if (!this.paused) ac.resume().then(sync, () => {}); };
    addEventListener("pointerdown", resume);
    addEventListener("keydown", resume);
    document.addEventListener("visibilitychange", () => { if (document.visibilityState === "visible") resume(); });
    resume();
  }

  // ── 输入 ──
  setMask(source: string, mask: number): void {
    if ((this.masks.get(source) ?? 0) === mask) return;
    this.masks.set(source, mask);
    if (mask) this.opts.onInput?.();
    let all = 0;
    for (const m of this.masks.values()) all |= m;
    this.core._kr_set_input(all >>> 0);
  }
  getMask(source: string): number { return this.masks.get(source) ?? 0; }
  setAnalog(x: number, y: number): void {
    if (x || y) this.opts.onInput?.();
    this.core._kr_set_analog(Math.round(x * 32767), Math.round(y * 32767));
  }
  /** 核堆用了多少字节（工具栏「内存」；老核没有这个导出 → 0）。核的堆固定 768 MB、不增长。 */
  heapUsed(): number { return this.core._kr_heap_used ? this.core._kr_heap_used() : 0; }
  /** 这一局读过的盘上字节并集的大小（核 mark_seen；挂机判定的进展信号）。老核没有这个导出 → 0。 */
  discSeenBytes(): number { return this.core._kr_disc_seen_bytes ? this.core._kr_disc_seen_bytes() : 0; }

  // ── 音量 / 静音（W-12：和设备硬件音量独立；user 10-14「一个和苹果硬件独立的音量和静音控制」）──
  private gain: GainNode | null = null;
  private vol = 1;
  private muted = false;
  get volume(): number { return this.vol; }
  get isMuted(): boolean { return this.muted; }
  setVolume(v: number): void { this.vol = Math.max(0, Math.min(1, v)); this.applyGain(); }
  setMuted(m: boolean): void { this.muted = m; this.applyGain(); }
  /** 内部的「先别出声」（「从上次开始」读档好之前；和人设的静音分开，不改 isMuted）。 */
  private held = false;
  setHold(h: boolean): void { this.held = h; this.applyGain(); }
  private applyGain(): void {
    if (!this.gain) return;
    // 平方曲线：滑杆中间听起来像「一半」（人耳对音量是对数的，线性滑杆后半段几乎没变化）
    const g = this.muted || this.held ? 0 : this.vol * this.vol;
    this.gain.gain.setTargetAtTime(g, this.ac.currentTime, 0.015); // 15 ms 平滑，不出咔哒声
  }

  // ── 截图（W-14）：核只抓一帧（不序列化整机状态），原生大小 RGBA、左上角原点 ──
  async captureFrame(): Promise<{ rgba: Uint8Array; w: number; h: number } | null> {
    const { core } = this;
    if (!core._kr_request_frame) return null; // 老核
    const before = core._kr_frame_shot_seq();
    core._kr_request_frame();
    await this.waitSeq(() => core._kr_frame_shot_seq(), before, 5000);
    const w = core._kr_thumb_w(), h = core._kr_thumb_h();
    return w > 0 && h > 0 ? { rgba: core.HEAPU8.slice(core._kr_thumb_ptr(), core._kr_thumb_ptr() + w * h * 4), w, h } : null;
  }
  inputMask(): number { return this.core._kr_get_input(); }

  // ── 暂停 / 快进 ──
  get paused(): boolean { return this.core._kr_get_paused() === 1; }
  setPaused(p: boolean): void {
    this.core._kr_set_paused(p ? 1 : 0);
    if (p) this.ac.suspend().catch(() => {});
    else this.ac.resume().catch(() => {});
  }
  get speed(): number { return this.core._kr_get_speed(); }
  setSpeed(x: number): void { this.core._kr_set_speed(x); }

  // ── 快照（核线程在帧边界做，暂停中也能做）──
  private waitSeq(getSeq: () => number, before: number, timeoutMs = 20000): Promise<void> {
    return new Promise((resolve, reject) => {
      const t0 = performance.now();
      const poll = () => {
        if (getSeq() !== before) return resolve();
        if (performance.now() - t0 > timeoutMs) return reject(new Error("core did not answer in time"));
        setTimeout(poll, 10);
      };
      poll();
    });
  }
  /** 存 / 读之前等核真正跑起来（出过 RUNNING_FRAMES 帧）：刚启动时 PPSSPP 的模拟线程还在「已请求启动」，上游 EmuThreadPause 遇到这个状态直接返回，
   *  存 / 恢复和刚起步的模拟线程撞在一起会把核卡死（10-14 流程测试抓到：「从上次开始」一开盘就读档 → core did not answer）。 */
  private async whenRunning(): Promise<void> {
    const t0 = performance.now(), f0 = this.stats().frames;
    try { await this.whenRunningInner(); } finally { console.info(`[resume] whenRunning waited ${(performance.now() - t0).toFixed(0)} ms (frames ${f0} → ${this.stats().frames})`); }
  }
  private async whenRunningInner(): Promise<void> {
    const t0 = performance.now();
    while (this.core._kr_stat_frames() < RUNNING_FRAMES) {
      if (performance.now() - t0 > 30_000) throw new Error("core is not running yet");
      await new Promise((r) => setTimeout(r, 50));
    }
  }

  /** 存整机状态；同一帧的画面（RGBA，左上角原点）一起交出来给缩略图用（取不到 = null）。 */
  async snapshot(): Promise<{ state: Uint8Array; frame: { rgba: Uint8Array; w: number; h: number } | null }> {
    await this.whenRunning();
    const { core } = this;
    const before = core._kr_snap_seq();
    core._kr_request_snapshot();
    await this.waitSeq(() => core._kr_snap_seq(), before);
    const size = core._kr_snap_size();
    if (!size) throw new Error("core returned no state");
    const state = core.HEAPU8.slice(core._kr_snap_ptr(), core._kr_snap_ptr() + size);
    core._kr_snap_free();
    const w = core._kr_thumb_w(), h = core._kr_thumb_h();
    const frame = w > 0 && h > 0 ? { rgba: core.HEAPU8.slice(core._kr_thumb_ptr(), core._kr_thumb_ptr() + w * h * 4), w, h } : null;
    return { state, frame };
  }
  async restore(bytes: Uint8Array): Promise<void> {
    await this.whenRunning();
    const { core } = this;
    const ptr = core._malloc(bytes.length);
    // 核的内存固定 768 MB、不增长：分配失败返回 0，往 0 写会把核写坏（之后表现为「core did not answer」）。先拦下、说清楚。
    if (!ptr) throw new Error(`core out of memory: cannot allocate ${(bytes.length / 2 ** 20).toFixed(0)} MB to restore a state`);
    core.HEAPU8.set(bytes, ptr);
    const before = core._kr_restore_seq();
    core._kr_request_restore(ptr, bytes.length);
    await this.waitSeq(() => core._kr_restore_seq(), before);
    if (!core._kr_restore_ok()) throw new Error("core rejected the state");
  }

  // ── 画面（每次显示器刷新调一次）──
  tick(): void {
    const { core, opts } = this;
    const seq = core._kr_frame_seq();
    const now = performance.now();
    this.perRefresh.dts.push(now - this.perRefresh.last);
    this.perRefresh.last = now;
    this.perRefresh.counts[Math.min(seq - this.perRefresh.seq, 2)]++;
    this.perRefresh.seq = seq;
    if (!this.hwChecked && seq > 0) {
      this.hwChecked = true;
      const hw = core._kr_hw_active() === 1;
      opts.glCanvas.hidden = !hw;
      opts.softCanvas.hidden = hw;
    }
    if (seq !== this.lastSeq && !core._kr_hw_active()) {
      this.lastSeq = seq;
      const w = core._kr_frame_w(), h = core._kr_frame_h();
      if (w > 0 && h > 0) {
        const c = opts.softCanvas;
        if (c.width !== w || c.height !== h) { c.width = w; c.height = h; this.image = null; }
        this.image ??= this.ctx2d.createImageData(w, h);
        const src = core.HEAPU8.subarray(core._kr_frame_ptr(), core._kr_frame_ptr() + w * h * 4);
        const dst = this.image.data;
        for (let i = 0; i < src.length; i += 4) { // XRGB8888（B,G,R,X）→ RGBA
          dst[i] = src[i + 2]; dst[i + 1] = src[i + 1]; dst[i + 2] = src[i]; dst[i + 3] = 255;
        }
        this.ctx2d.putImageData(this.image, 0, 0);
      }
    }
  }

  // ── 统计（状态栏和自动化测试用）──
  stats() {
    const { core, ac } = this;
    const now = performance.now();
    const frames = core._kr_stat_frames();
    const fw = this.fpsWindow;
    if (now - fw.t >= 1000) {
      const emuMs = core._kr_stat_emu_ms();
      fw.fps = ((frames - fw.frames) * 1000) / (now - fw.t);
      fw.speed = (emuMs - fw.emuMs) / (now - fw.t);
      const n = this.net;
      n.bps = (n.bytes * 1000) / (now - fw.t); n.waitPerSec = (n.waitMs * 1000) / (now - fw.t);
      n.bytes = 0; n.waitMs = 0;
      fw.t = now; fw.frames = frames; fw.emuMs = emuMs;
      core._kr_pace_stats(this.paceBuf);
      const f = core.HEAPF64.subarray(this.paceBuf >> 3, (this.paceBuf >> 3) + 8);
      this.pace = { mean: f[1], sd: f[2], max: f[3], late: f[4], bunched: f[5], frameMs: f[6], frameMsSd: f[7] };
      const sorted = this.perRefresh.dts.slice().sort((a, b) => a - b);
      this.perRefresh.hz = sorted.length ? 1000 / sorted[sorted.length >> 1] : 0;
      this.perRefresh.shown = this.perRefresh.counts;
      this.perRefresh.dts = [];
      this.perRefresh.counts = [0, 0, 0];
    }
    const pacing = core._kr_get_pacing();
    return {
      frames,
      fps: fw.fps,
      speed: fw.speed,
      pace: this.pace,
      displayHz: this.perRefresh.hz,
      perRefresh: this.perRefresh.shown,
      pacing: ["墙钟", "声音", "跟屏幕"][pacing] + (pacing === 2 ? ["（按时间对齐）", "（每刷新 1 帧）"][core._kr_vsync_lock()] : ""),
      catchup: core._kr_catchup_runs(),
      reanchors: core._kr_reanchors(),
      frameskip: core._kr_frameskip(),
      renderer: core._kr_hw_active() ? "GPU（WebGL2）" + ["", " · 低延迟画布：浏览器采纳", " · 低延迟画布：浏览器没采纳"][core._kr_desync_state()] : "软件渲染",
      bytesFetched: core._kr_stat_bytes_fetched(),
      readsWaiting: core._kr_stat_reads_waiting(),
      mediaReads: this.mediaReads,
      /** 这一秒读盘拿到的字节 / 秒。 */
      netBps: this.net.bps,
      /** 这一秒里核等读盘等了多少毫秒（接近 1000 = 整秒都在等网）。 */
      netWaitMs: this.net.waitPerSec,
      netInflight: this.net.inflight,
      audioState: ac.state,
      audioClock: ac.currentTime,
      audioRead: core.HEAP32[core._kr_audio_r_ptr() >> 2],
      audioFillMs: core._kr_audio_fill() / 44.1,
      audioUnderrunMs: core.HEAP32[core._kr_audio_underrun_ptr() >> 2] / 44.1,
      audioDropped: core._kr_audio_dropped(),
      outputLatencyMs: ((ac.outputLatency || 0) + (ac.baseLatency || 0)) * 1000,
      paused: this.paused,
      gameSpeed: this.speed,
      seconds: (now - this.startedAt) / 1000,
    };
  }

  // ── 记忆棒（游戏内存档）：核的文件系统在主线程，直接读 ──
  /** 每个存档目录的「指纹」（文件路径 + 大小 + 修改时间），用来发现游戏存了档 / 删了档。 */
  memstickDirs(): Map<string, string> {
    const FS = this.core.FS;
    const out = new Map<string, string>();
    if (!FS.analyzePath(MEMSTICK_DIR).exists) return out;
    for (const dir of FS.readdir(MEMSTICK_DIR)) {
      if (dir === "." || dir === ".." || !FS.isDir(FS.stat(`${MEMSTICK_DIR}/${dir}`).mode)) continue;
      const parts: string[] = [];
      this.walk(`${MEMSTICK_DIR}/${dir}`, dir, (rel, st) => parts.push(`${rel}:${st.size}:${st.mtime.getTime()}`));
      out.set(dir, parts.sort().join("|"));
    }
    return out;
  }
  /** 读一个存档目录（键 = 「目录/文件」）。 */
  readSaveDir(dir: string): Map<string, Uint8Array> {
    const files = new Map<string, Uint8Array>();
    this.walk(`${MEMSTICK_DIR}/${dir}`, dir, (rel) => files.set(rel, this.core.FS.readFile(`${MEMSTICK_DIR}/${rel}`)));
    return files;
  }
  private walk(dir: string, rel: string, visit: (rel: string, st: { size: number; mtime: Date }) => void): void {
    const FS = this.core.FS;
    if (!FS.analyzePath(dir).exists) return;
    for (const name of FS.readdir(dir)) {
      if (name === "." || name === "..") continue;
      const st = FS.stat(`${dir}/${name}`);
      const r = rel ? `${rel}/${name}` : name;
      if (FS.isDir(st.mode)) this.walk(`${dir}/${name}`, r, visit);
      else visit(r, st);
    }
  }
}
