//   自己的 SW = 这一页目录下那个 service-worker.js；自己的缓存 = 本频道前缀（和 service-worker.js 同一条规矩）。added 20261014 by Claude Opus 5.5
const IS_DEV_CHANNEL = location.pathname.includes("/dev/") || DEV_SERVER;
const CACHE_PREFIX = IS_DEV_CHANNEL ? "kudsrocket-dev-" : "kudsrocket-prod-";
const ownCache = (k: string) => k.startsWith(CACHE_PREFIX) || (IS_DEV_CHANNEL && /^kudsrocket-(?!dev-|prod-)/.test(k)); // 后一半 = 频道分开之前的老缓存（只有 dev 用过）
const OWN_SW = new URL("./service-worker.js", location.href).href;
const ownController = () => navigator.serviceWorker.controller?.scriptURL === OWN_SW;

// ── 跨源隔离：多线程核要 SharedArrayBuffer。GitHub Pages 设不了响应头，由 service worker 补（service-worker.js）。──
async function ensureIsolation(): Promise<boolean> {
  if (!("serviceWorker" in navigator)) return crossOriginIsolated;
  const reg = await navigator.serviceWorker.register("./service-worker.js").catch((e) => { console.warn("[sw]", e); return null; });
  navigator.serviceWorker.addEventListener("message", (e) => { if (e.data?.type === "asset-updated") showUpdate(); }); // 第 3 路：SW 看到 ETag 变了
  if (reg) watchUpdates(reg);
  if (crossOriginIsolated) return true;
  if (!reg || ownController()) return false; // 自己的 service worker 已经在管这一页却还不隔离 = 浏览器不支持
  // 还没人管、或者管着的是别的频道的（先开过 prod 再第一次开 /dev/：根的 SW 先管着这页）→ 等自己的接管
  while (!ownController()) await new Promise((r) => navigator.serviceWorker.addEventListener("controllerchange", r, { once: true }));
  location.reload();
  return new Promise<boolean>(() => {});
}

// 家族 4 路更新检测（MyPWAPatterns sw-shell-and-deploy）：① 注册时已有 waiting ② 新 SW 装好 ③ SW 看到资源变了 ④ 回前台 / 得到焦点 / 每 10 分钟主动 update()（iPad 从不自己查，这一路是命门）。
//   永不自动重载（人可能正在玩）；提示上的「重新载入」才换版本。user 10-14「pwa强制更新的之类的也都没做，也需要做一下」。added 20261014 by Claude Fable 5.1
function watchUpdates(reg: ServiceWorkerRegistration): void {
  const live = ownController; // 第一次安装（还没被自己的 SW 管过）不算更新
  if (reg.waiting && live()) showUpdate();
  reg.addEventListener("updatefound", () => {
    const w = reg.installing;
    w?.addEventListener("statechange", () => { if ((w.state === "installed" || w.state === "activated") && live()) showUpdate(); });
  });
  const check = () => { if (document.visibilityState === "visible") reg.update().catch(() => {}); };
  document.addEventListener("visibilitychange", check);
  addEventListener("focus", check);
  setInterval(check, 10 * 60_000);
}

function showUpdate(): void {
  const el = $("update");
  if (!el.hidden) return;
  const close = h("button", { class: "icon-btn", title: "先不管" }, icon("x"));
  close.addEventListener("click", () => { el.hidden = true; });
  el.replaceChildren(h("span", {}, "有新版本"), h("button", { class: "primary", onclick: () => location.reload() }, session ? "重新载入（会退出当前这张盘）" : "重新载入"), close);
  el.hidden = false;
}

/** 强制更新 = 注销管着这一页的 service worker + 只删自己前缀的缓存 + 重载（家规：兄弟 app 的壳和 pwa-models 不碰）。IDB / 云端数据不动。 */
async function forceUpdate(): Promise<void> {
  if (!(await confirmSheet("强制更新？", `现在是 ${APP_VERSION}。会清掉这个 app 自己的离线壳缓存并重新载入${session ? "（会退出当前这张盘）" : ""}；存档、快照、登录状态都不动。${inFlight() ? "⚠ 有东西正在传，重新载入会打断它（快照会留在本机等续传；上传中的盘得重传）。" : ""}`, "更新"))) return;
  try {
    const reg = await navigator.serviceWorker?.getRegistration();
    await reg?.unregister();
    const keys = await caches.keys();
    await Promise.all(keys.filter(ownCache).map((k) => caches.delete(k))); // 只删本频道的（prod / dev 同一个域名）
  } catch (e) { console.warn("[force-update]", e); }
  location.reload();
}

