/** 点一张盘：从上次开始 / 从头玩 / 存档管理 / 取消（user 10-14「游戏点进去也是从上次开始玩 从头玩 存档管理 取消等选项」）。 */
async function discMenu(identifier: string): Promise<void> {
  const card = cards.get(identifier);
  const title = card?.title ?? (identifier.endsWith(".wafter") ? "这张盘" : stemOf(identifier));
  const choice = await sheet<"resume" | "fresh" | "saves" | "cache">((done) => [
    h("h2", {}, title),
    h("div", { class: "menu" },
      h("button", { class: "primary", onclick: () => done("resume") }, "从上次开始（读最新的快照）"),
      h("button", { onclick: () => done("fresh") }, "从头开始（不读快照）"),
      h("button", { onclick: () => done("saves") }, "存档管理"),
      pantryItems.find((it) => it.identifier === identifier)?.syncState === "cloud-only"
        ? h("button", { onclick: () => done("cache") }, "缓存全盘（整张留在这台设备：离线也能打开，不再等网）") : null,
      h("button", { onclick: () => done(null) }, "取消")),
  ]);
  if (choice === "cache") { cacheWholeDisc(identifier).catch((e) => banner(errorText(e))); return; }
  if (choice === "resume" || choice === "fresh") playFromPantry(identifier, choice === "resume");
  else if (choice === "saves") await openSaveManager({ ...saveManagerContext, only: card ? { title: card.title, key: card.key, discId: card.fp.id } : undefined });
}

