/** 缓存全盘（user 10-14「加一个cache全盘的功能」）：整张盘留在这台设备——之后读盘不走网，登录过期 / 断网也不会让游戏停住。
 *  库的 keepOffline 会复用流式读时已经拉过的片、只补缺口；进度走常驻状态条（不是 toast）。游戏里也能点（边玩边缓存，读盘优先）。 */
async function cacheWholeDisc(identifier: string): Promise<void> {
  const f = getStore().file(identifier, { mode: "existing" });
  if (await f.isKeptOffline()) { say("这张盘已经在这台设备上了"); return; }
  const size = pantryItems.find((it) => it.identifier === identifier)?.size ?? 0;
  const name = cards.get(identifier)?.title ?? stemOf(identifier);
  const r = await trackUpload(`盘 ${name}`, size, async (onProgress) => {
    await f.keepOffline({ onProgress });
    const ok = await f.isKeptOffline();
    return { pushed: ok, reason: ok ? undefined : "没留成（看横条）" };
  }, "缓存");
  if (r.pushed) say(`「${name}」整张在这台设备上了：离线也能打开，不再等网`, 6000);
  watchPantry();
  if (session && current?.identifier === identifier) renderToolbar();
}
const keepDisc = cacheWholeDisc;
async function offloadDisc(identifier: string): Promise<void> {
  try { await getStore().file(identifier, { mode: "existing" }).offload(); say("已移除这台设备上的副本"); }
  catch (e) { banner(`没移除：${errorText(e)}`); }
}

async function unlockTitles(): Promise<void> {
  let pw = getPassword(); // 这一页已经有口令（输过 / 这台设备记着）就不再问
  if (!pw) {
    pw = await askPassword("输入口令", "加密盘的名字要口令才看得见。", { offerRemember: true });
    if (!pw) return;
    adoptPassword(pw);
  }
  let wrong = 0;
  // 每张加密盘要从云端拉一片读尾部元数据：并行着拉（user 10-14「我传了5-6个盘，现在onedrive ls很慢」——原来是一张接一张）
  const todo = pantryItems.filter((it) => it.identifier.endsWith(".wafter") && !cards.has(it.identifier)).map((it) => it.identifier);
  let next = 0;
  const worker = async () => {
    while (next < todo.length) {
      const id = todo[next++];
      try {
        const card = await inspectPantry(id);
        if (card) { cards.set(id, card); renderLibrary(); } else wrong++;
      } catch (e) { banner(`读名字失败：${errorText(e)}`, "warning"); }
    }
  };
  await Promise.all(Array.from({ length: Math.min(4, todo.length) }, worker));
  if (wrong) say(`${wrong} 张盘这个口令打不开`);
}

