      return h("div", { class: "slot" }, thumb,
        h("div", { class: "slot-text" }, h("span", { class: "slot-name" }, slotLabel(it)), h("span", { class: "muted" }, new Date(it.savedAt).toLocaleString())),
        h("div", { class: "slot-buttons" },
          h("button", { onclick: async () => { done(); if (await confirmSheet("移到回收站？", "主页「回收站 / 备份箱」里能恢复。", "移到回收站")) s.remove(it.id).catch((e) => banner(errorText(e))); } }, "删"),
          h("button", { class: "primary", onclick: () => { done(); loadFrom(it); } }, "读")));
