// ── 截图（W-14）：核抓一帧原生大小 → 壳注入的编码动词 → 预览面板里选倍数 / 格式，点「分享」（系统分享面板）或「保存」──
//   分享要在用户手势里调：抓帧 + 编码是异步的，等它们做完手势早过了，所以先出预览、再让人点（user 10-14「截图分享功能，走分享按钮，原生大小」）。
//   默认 ×3 最近邻 + PNG（user 10-14「加一个pixel art放大的模式方便社交媒体分享」「默认jpg够了吧」→ 建议 PNG：放大后像素是整块，PNG 压得省，
//   JPG 在字和像素边上起毛刺；平台反正会再压一遍）。选项先不记住（记住 = 新的持久化，等设置深模块 W-17）。
const SHOT_SCALES = [1, 2, 3, 4] as const;
/** 截图按钮：手指 / 鼠标**按下**那一刻就向核要帧（click 要等抬起，差一两百毫秒，一闪而过的画面就没了；user 10-14「截图应该是按下去的立刻那一张」）。
 *  键盘（回车 / 空格）没有 pointerdown，走 click 兜底。 */
function shotButton(): HTMLButtonElement {
  const b = h("button", { class: "icon-btn", title: "截图（按下那一刻；分享 / 保存）", "aria-label": "截图" }, h("span", { class: "label" }, "截图")) as HTMLButtonElement;
  let viaPointer = false;
  const go = () => { shareScreenshot().catch((e) => banner(`截图失败：${errorText(e)}`)); };
  b.addEventListener("pointerdown", (e) => { if (e.button !== 0) return; viaPointer = true; go(); });
  b.addEventListener("click", () => { if (viaPointer) { viaPointer = false; b.blur(); return; } go(); b.blur(); });
  return b;
}
async function shareScreenshot(): Promise<void> {
  if (!session) return;
  const frame = await session.captureFrame();
  if (!frame) { banner("这个核版本抓不了画面，重新载入试试。"); return; }
  const stamp = new Date().toISOString().replace(/[-:]/g, "").replace("T", "-").slice(0, 15);
  let scale: number = 3, type: "png" | "jpg" = "png";
  let file: File | null = null, url = "";
  const img = h("img", { class: "shot", alt: "" }) as HTMLImageElement;
  const info = h("p", { class: "muted" }, "…");
  const shareBtn = h("button", { class: "primary" }, "分享") as HTMLButtonElement;
  const saveBtn = h("button", {}, "保存") as HTMLButtonElement;
  const render = async () => {
    const bytes = await canvasVerbs.encodeImage(frame.rgba, frame.w, frame.h, { scale, type });
    file = new File([bytes as BlobPart], `KudsRocket-${stamp}${scale > 1 ? `-x${scale}` : ""}.${type}`, { type: type === "png" ? "image/png" : "image/jpeg" });
    if (url) URL.revokeObjectURL(url);
    url = URL.createObjectURL(file);
    img.src = url;
    info.textContent = `${frame.w * scale}×${frame.h * scale}${scale > 1 ? `（原生 ${frame.w}×${frame.h} × ${scale}，像素放大）` : "（原生大小）"} · ${type.toUpperCase()} · ${(file.size / 1024).toFixed(0)} KB`;
    const canShare = !!navigator.canShare?.({ files: [file] });
    shareBtn.hidden = !canShare;
    saveBtn.className = canShare ? "" : "primary";
  };
  const seg = <T extends string | number>(choices: readonly T[], get: () => T, set: (v: T) => void, label: (v: T) => string) => {
    const box = h("div", { class: "seg" });
    const paint = () => { for (const b of Array.from(box.children)) b.classList.toggle("on", (b as HTMLElement).dataset.v === String(get())); };
    for (const c of choices) box.append(h("button", { "data-v": String(c), onclick: () => { set(c); paint(); render().catch((e) => banner(errorText(e))); } }, label(c)));
    paint();
    return box;
  };
  shareBtn.addEventListener("click", () => { if (file) navigator.share({ files: [file] }).catch((e) => { if ((e as Error).name !== "AbortError") banner(`分享失败：${errorText(e)}`); }); });
  saveBtn.addEventListener("click", () => { if (!file) return; const a = h("a", { href: url, download: file.name }); document.body.append(a); a.click(); a.remove(); });
  await render();
  await sheet<void>((done) => [
    h("h2", {}, "截图"),
    img,
    info,
    h("div", { class: "row" }, seg(SHOT_SCALES, () => scale, (v) => { scale = v; }, (v) => (v === 1 ? "原生" : `×${v}`)),
      seg(["png", "jpg"] as const, () => type, (v) => { type = v; }, (v) => v.toUpperCase())),
    h("div", { class: "row" }, shareBtn, saveBtn, h("button", { onclick: () => done() }, "关闭")),
  ]);
  if (url) URL.revokeObjectURL(url);
}

function togglePause(): void {
  if (!session) return;
  session.setPaused(!session.paused);
  renderToolbar();
}
function setFast(on: boolean): void {
  if (!session) return;
  session.setSpeed(on ? FAST_FORWARD : 1);
  renderToolbar();
}
// 软键默认开；第一次真的来了手柄 / 键盘的游戏键输入才自动收起（只一次）；用户在菜单里主动开 / 关过就再也不自动切
//   （user 10-15「默认开软键盘，只有真的遇到一次硬件输入或者键盘输入之后才关。不然在quest上面你老是误判。但是用户如果主动选了就不自动切」）。
//   以前按 (pointer: coarse) 猜 → Quest 的浏览器猜不准。added 20261015 by Claude Fable 5.1
let softKeysChoice: "auto" | "user" = "auto";
let hardwareSeen = false;
function toggleSoftKeys(): void {
  softKeysChoice = "user";
  softKeys?.setVisible(!softKeys.visible);
  renderToolbar();
}
function hardwareInput(kind: "手柄" | "键盘"): void {
  if (hardwareSeen) return;
  hardwareSeen = true;
  if (softKeysChoice !== "auto" || !softKeys?.visible) return;
  softKeys.setVisible(false);
  renderToolbar();
  say(`用上${kind}了，屏幕软键先收起（菜单里能再打开）`, 4000);
}
function toggleFullscreen(): void {
  if (document.fullscreenElement) document.exitFullscreen().catch(() => {});
  else $("stage").requestFullscreen({ navigationUI: "hide" }).catch((e) => say(`全屏失败：${errorText(e)}`));
}
async function quit(): Promise<void> {
  // 退出不强制存快照（user 10-14「退出应该不强制存快照」）：只把游戏自己存的档同步完；快照要的话自己按。切到后台那份自动快照照旧。
  const ok = await confirmSheet("退出？", "存档会先同步完再退出；不会自动存快照。", "退出");
  if (!ok) return;
  // 同步要等一下（几百毫秒到几秒）：给人看得见的进度，别像没反应（user 10-14「为什么每次退出要点两次」）。
  // 卡住了可以「不等了」：没传完的留在这台设备（IDB 里是 dirty），下次存档管理里「推一把」或自动续传。
  let leaveNow = false;
  const status = h("p", { class: "muted" }, syncState.text || "正在同步…");
  const off = subscribeSync((s) => { status.textContent = s.text || "正在同步…"; });
  const closing = sheet<"leave">((done) => [
    h("h2", {}, "正在退出…"),
    status,
    h("div", { class: "row" }, h("button", { onclick: () => done("leave") }, "不等了，直接退出")),
  ], { dismissable: false }).then((v) => { if (v === "leave") { leaveNow = true; location.reload(); } });
  try {
    if (!leaveNow) await jamTick(true);
    if (!leaveNow) await whenIdle();   // 正在传的快照 / 盘也等完（user 10-14「用户会不会不知道要等上传完再按叉？」）；「不等了」仍能走
  } finally { off(); }
  void closing;
  if (!leaveNow) location.reload();
}

// ── 每次刷新：画面、手柄、状态 ──
const PAD_MAP: [number, ButtonName][] = [[0, "cross"], [1, "circle"], [2, "square"], [3, "triangle"], [4, "l"], [5, "r"], [6, "l"], [7, "r"],
  [8, "select"], [9, "start"], [12, "up"], [13, "down"], [14, "left"], [15, "right"]];
const STICK_DEADZONE = 0.12;
let padInfo = "";
/** 右摇杆 → 十字键：推过一半算按下，斜着推 = 两个方向一起。 */
function rightStickMask(x: number, y: number): number {
  return (x < -0.5 ? bit("left") : 0) | (x > 0.5 ? bit("right") : 0) | (y < -0.5 ? bit("up") : 0) | (y > 0.5 ? bit("down") : 0);
}
function pollGamepads(s: CoreSession): void {
  // 每帧重列：热插拔自然生效；多个手柄合并给 1P，摇杆取推得最远的那个。
  // 左摇杆：软键 / 键盘 / 手柄里推得最远的那个；右摇杆（PSP 没有）→ 十字键（怪物猎人那类拿十字键转视角；软键右摇杆同一个映射）
  let mask = rightStickMask(softRight.x, softRight.y), ax = softAnalog.x, ay = softAnalog.y;
  if (Math.hypot(keyAnalog.x, keyAnalog.y) > Math.hypot(ax, ay)) { ax = keyAnalog.x; ay = keyAnalog.y; }
  const names: string[] = [];
  let pressed = false; // 真按了（键 / 摇杆推出死区），不是光插着
  for (const gp of navigator.getGamepads?.() ?? []) {
    if (!gp || !gp.connected) continue;
    names.push(gp.id.slice(0, 40) + (gp.mapping === "standard" ? "" : "（非标准布局，键位可能不对）"));
    for (const [i, name] of PAD_MAP) if (gp.buttons[i]?.pressed) { mask |= bit(name); pressed = true; }
    const x = gp.axes[0] ?? 0, y = gp.axes[1] ?? 0;
    if (Math.hypot(x, y) > STICK_DEADZONE) { pressed = true; if (Math.hypot(x, y) > Math.hypot(ax, ay)) { ax = x; ay = y; } }
    const rm = rightStickMask(gp.axes[2] ?? 0, gp.axes[3] ?? 0);
    if (rm) pressed = true;
    mask |= rm;
  }
  padInfo = names.join(" + ");
  if (pressed) hardwareInput("手柄");
  s.setMask("pad", mask);
  s.setAnalog(ax, ay);
}

let statusAt = 0;
let lastFrameAt = performance.now();
function frame(): void {
  if (!session) return;
  pollGamepads(session);
  session.tick();
  const now = performance.now();
  if (activity) {
    activity.discSeen(session.discSeenBytes(), now);
    snaps?.tick(activity.tick(now - lastFrameAt, now, { visible: document.visibilityState === "visible", paused: session.paused }));
  }
  lastFrameAt = now;
  if (now - statusAt > 500) { statusAt = now; renderHud(); if (!$("status").hidden) $("status").textContent = statusText(); }
  requestAnimationFrame(frame);
}

function statusText(): string {
  const s = session!.stats();
  return [
    `${APP_VERSION} · ${s.fps.toFixed(1)} fps · 速度 ${(s.speed * 100).toFixed(0)}% · ${s.renderer} · 限速：${s.pacing}${s.paused ? " · 暂停中" : ""}${s.gameSpeed > 1 ? ` · 快进 ×${s.gameSpeed}` : ""}`,
    `画面节奏：出帧间隔 ${s.pace.mean.toFixed(1)} ± ${s.pace.sd.toFixed(1)} ms · 最长 ${s.pace.max.toFixed(0)} ms · 跳帧 ${["关", "每 2 帧画 1", "每 3 帧画 1"][s.frameskip]} · 追进度 ${s.catchup} 帧 · 重新对齐 ${s.reanchors} 次`,
    `显示器 ≈ ${s.displayHz.toFixed(0)} Hz · 每次刷新看到新帧：0 张 ${s.perRefresh[0]} · 1 张 ${s.perRefresh[1]} · 2 张以上 ${s.perRefresh[2]}（每秒）`,
    `盘：这一秒 ${(s.netBps / 1024).toFixed(0)} KB/s · 等读盘 ${s.netWaitMs.toFixed(0)} ms/s${s.netInflight ? `（正在等 ${s.netInflight} 个）` : ""} · 累计 ${(s.bytesFetched / 2 ** 20).toFixed(1)} MB / ${s.mediaReads} 次`,
    `声音：${s.audioState} · 缓冲 ${s.audioFillMs.toFixed(0)} ms · 输出延迟 ${s.outputLatencyMs.toFixed(0)} ms · 欠载累计 ${s.audioUnderrunMs.toFixed(0)} ms · 丢弃 ${s.audioDropped}`,
    `手柄：${padInfo || "没检测到（插上后在页面上按一下手柄按键）"}`,
    `活动：${activity ? { playing: "运行中", idle: "挂机（自动快照不计时）", away: "后台 / 暂停" }[activity.state(performance.now(), { visible: document.visibilityState === "visible", paused: s.paused })] : "—"} · 读过的盘 ${(session!.discSeenBytes() / 2 ** 20).toFixed(1)} MB · 这次运行 ${(((activity?.playedMs) ?? 0) / 60_000).toFixed(1)} 分钟`,
    `键盘（同 PPSSPP 默认）：方向键 十字 · I/J/K/L 摇杆（右 Shift 轻推）· X ○ · Z × · A □ · S △ · Q/W L/R · 空格 Start · V / 回车 Select · Esc / P 暂停 · 按住 Tab 快进 · \` 快进开关 · M 静音 · F2 存 / F4 读当前格`,
  ].join("\n");
}

// ── 键盘 ──
// 键位照 PPSSPP Windows 版默认（user 的 PC 肌肉记忆；上游 Core/KeyMapDefaults.cpp defaultQwertyKeyboardKeyMap）：
//   □ A · △ S · ○ X · × Z · L Q · R W · Start 空格 · Select V（非 Windows 版是回车，两个都认）· 十字 方向键 · 摇杆 I / J / K / L（按住右 Shift = 轻推）
//   · 快进 按住 Tab / ` 切换 · 暂停 Esc（P 也行）。edited 20261014 by Claude Opus 5.5（之前回车 = Start、空格 = Select，和 PPSSPP 正好反了）
const KEYMAP: Record<string, ButtonName> = { ArrowUp: "up", ArrowDown: "down", ArrowLeft: "left", ArrowRight: "right", KeyX: "circle", KeyZ: "cross", KeyA: "square", KeyS: "triangle", Space: "start", KeyV: "select", Enter: "select", KeyQ: "l", KeyW: "r" };
const STICK_KEYS: Record<string, [number, number]> = { KeyI: [0, -1], KeyK: [0, 1], KeyJ: [-1, 0], KeyL: [1, 0] };
const stickKeysDown = new Set<string>();
let keyAnalog = { x: 0, y: 0 };
function updateKeyAnalog(lightly: boolean): void {
  let x = 0, y = 0;
  for (const k of stickKeysDown) { x += STICK_KEYS[k][0]; y += STICK_KEYS[k][1]; }
  const len = Math.hypot(x, y) || 1, mag = lightly ? 0.5 : 1;
  keyAnalog = { x: (x / len) * mag, y: (y / len) * mag };
}
let rightShift = false;
function onKey(e: KeyboardEvent, down: boolean): void {
  if (!session || isSheetOpen()) return;
  if (down && e.code === "Enter" && e.altKey) { e.preventDefault(); toggleFullscreen(); return; } // 先于键位表：别同时按下 Start
  if (e.code === "Tab") { e.preventDefault(); if (!e.repeat) setFast(down); return; }
  if (STICK_KEYS[e.code]) { e.preventDefault(); if (down) { stickKeysDown.add(e.code); hardwareInput("键盘"); } else stickKeysDown.delete(e.code); updateKeyAnalog(e.getModifierState?.("Shift") && e.location === 2 || rightShift); return; }
  if (e.code === "ShiftRight") { rightShift = down; updateKeyAnalog(down); return; }
  if (down && !e.repeat) {
    if (e.code === "KeyP" || e.code === "Escape") { e.preventDefault(); togglePause(); return; }
    if (e.code === "Backquote") { e.preventDefault(); setFast(!(session.speed > 1)); return; }
    if (e.code === "KeyM") { e.preventDefault(); toggleMute(); return; }
    if (e.code === "F2") { e.preventDefault(); const t = quickSlot(true); if (t) saveTo(t); return; }
    if (e.code === "F4") { e.preventDefault(); const t = quickSlot(false); if (t) loadFrom(t); return; }
  }
  const b = KEYMAP[e.code];
  if (!b) return;
  e.preventDefault();
  if (down) hardwareInput("键盘");
  const m = session.getMask("keyboard");
  session.setMask("keyboard", down ? m | bit(b) : m & ~bit(b));
}

// ── 工具：做加密盘 / 解密盘（写成这台电脑上的文件）──
function progressSheet(title: string): { p: Progress; close(): void } {
  let cancelled = false;
  let finish: (v: null) => void = () => {};
  const bar = h("progress", { max: "1", value: "0" });
  const text = h("span", { class: "muted" }, "");
  sheet<null>((done) => {
    finish = done;
    return [h("h2", {}, title), bar, text,
      h("div", { class: "row" }, h("button", { onclick: () => { cancelled = true; } }, "取消"))];
  }, { dismissable: false });
  const t0 = performance.now();
  return {
    p: {
      update(d, total) {
        (bar as HTMLProgressElement).value = d / total;
        const mbs = d / 2 ** 20 / ((performance.now() - t0) / 1000);
        text.textContent = `${(d / 2 ** 30).toFixed(2)} / ${(total / 2 ** 30).toFixed(2)} GB · ${mbs.toFixed(0)} MB/s`;
      },
      get cancelled() { return cancelled; },
    },
    close: () => finish(null),
  };
}

async function askNewPassword(): Promise<string | null> {
  for (;;) {
    const a = await askPassword("设口令", "以后打开要用同一个口令。口令不存，忘了就打不开。");
    if (!a) return null;
    const b = await askPassword("再输一次", "确认刚才的口令。");
    if (b === null) return null;
    if (a === b) return a;
    banner("两次输入不一样，再来一次。", "warning");
  }
}

async function makeWafer(): Promise<void> {
  const [handle] = await showOpenFilePicker!();
  const input = await handle.getFile();
  const pw = await askNewPassword();
  if (!pw) return;
  const out = await showSaveFilePicker!({ suggestedName: `${randomStem()}.wafter` });
  const ui = progressSheet("正在加密…");
  try {
    await encryptToLocal(input, pw, out, ui.p);
    say(`做好了：${out.name}。放进 OneDrive 本 app 文件夹的 ${PANTRY}/ 就能在列表里看到。`, 10_000);
  } catch (e) {
    if (e instanceof Cancelled) say("取消了，没留下半成品"); else throw e;
  } finally { ui.close(); }
}

async function unwrapWafer(): Promise<void> {
  const [handle] = await showOpenFilePicker!({ types: [{ description: "wafter", accept: { "application/octet-stream": [".wafter"] } }] });
  const input = await handle.getFile();
  const opened = await withPassword(async (pw) => {
    const p = pw ?? getPassword();
    if (!p) throw new NeedPassword();
    return openForDecrypt(input, p);
  }, "这个文件");
  if (!opened) return;
  const out = await showSaveFilePicker!({ suggestedName: opened.name });
  const ui = progressSheet("正在解密…");
  try {
    await opened.write(out, ui.p);
    say(`解好了：${out.name}`, 6000);
  } catch (e) {
    if (e instanceof Cancelled) say("取消了，没留下半成品"); else throw e;
  } finally { ui.close(); }
}

const toolErr = (e: unknown) => { if ((e as { name?: string })?.name !== "AbortError") banner(errorText(e)); }; // AbortError = 人在选文件时点了取消

/** 上传盘：选本机文件 → 设口令 → 边加密边传进 pantry/（store 0.17.0 流式上传，不留本机副本）。进度走状态条。 */
async function uploadWafer(file: File): Promise<void> {
  // 重传护栏（user 10-14「没有对重新上传的护栏的话…」）：同一张盘再传一份 = 食品柜里两份。按盘号 + 版本 + 大小和已解锁名字的盘比对，一样的先问。
  const label = await readDiscLabel({ size: file.size, read: async (o, n) => new Uint8Array(await file.slice(o, o + n).arrayBuffer()) });
  const twin = [...cards.entries()].find(([, c]) => c.fp.size === file.size && (c.fp.id ?? null) === (label?.id ?? null) && (c.fp.v ?? null) === (label?.version ?? null));
  const locked = pantryItems.filter((it) => it.identifier.endsWith(".wafter") && !cards.has(it.identifier)).length;
  if (twin && !(await confirmSheet("食品柜里好像已经有这张盘了", `「${twin[1].title}」（${stemOf(twin[0])}）盘号、版本、大小都一样。还要再传一份吗？`, "还是传", "不传"))) return;
  if (!twin && locked) say(`有 ${locked} 张盘还没输口令看名字，没法比对是不是传过了`, 6000);
  const pw = await askNewPassword();
  if (!pw) return;
  const identifier = `${PANTRY}/${randomStem()}.wafter`;
  await trackUpload(`盘 ${file.name}`, file.size, (onProgress) => uploadToPantry(file, pw, identifier, onProgress).then(() => ({ pushed: true })));
  say(`传好了：${file.name}。关掉这一页前别清浏览器数据也没关系——它没留本机副本。`, 8000);
  watchPantry();
}

async function clearCache(): Promise<void> {
  if (!(await confirmSheet("清本机缓存？", "放掉所有已经同步到 OneDrive 的本机副本（盘、存档、快照）；没传上去的、只在这台设备上的一律不动。要离线玩的盘之后再「留在这台设备」。", "清"))) return;
  try {
    const r = await withBusyNote("正在清本机缓存…", () => clearLocalCopies([PANTRY, jarFolder(PLATFORM_CODE.psp), CRUMBS]));
    banner(`放掉了 ${r.dropped} 个本机副本（约 ${(r.bytes / 2 ** 20).toFixed(0)} MB）${r.kept ? `；${r.kept} 个没动（没传上去 / 只在本机 / 云端拿不到）` : ""}。流式暂存区由库按上限自己清。`, "warning");
    watchPantry();
  } catch (e) { banner(`清缓存失败：${errorText(e)}`); }
}
async function withBusyNote<T>(text: string, fn: () => Promise<T>): Promise<T> { say(text, 600_000); try { return await fn(); } finally { note("", 1); } }

// ── 开机 ──
async function boot(): Promise<void> {
  mountIcons();
  mountOverlays();
  $("version").textContent = APP_VERSION;
  $("version").title = "点一下：强制更新";
  $("version").addEventListener("click", () => { forceUpdate().catch((e) => banner(errorText(e))); });
  $("force-update").addEventListener("click", () => { forceUpdate().catch((e) => banner(errorText(e))); });
  if (!(await ensureIsolation())) {
    $("library").replaceChildren(h("p", {}, "这个浏览器用不了（跨源隔离没生效）。请换最新版的 Chrome / Edge / Safari。"));
    return;
  }
  softKeys = mountSoftKeys($("stage"), {
    onMask: (m) => session?.setMask("soft", m),
    onLeftStick: (x, y) => { softAnalog = { x, y }; },
    onRightStick: (x, y) => { softRight = { x, y }; },
    onPause: togglePause,
    onFast: (d) => setFast(d),
  });
  softKeys.setVisible(true); // 默认开（见 hardwareInput）
  $("stage").addEventListener("dblclick", (e) => { if (!(e.target as HTMLElement).closest(".softkeys .pk, .softkeys .dpad")) toggleFullscreen(); });
  addEventListener("keydown", (e) => onKey(e, true));
  addEventListener("keyup", (e) => onKey(e, false));
  addEventListener("blur", () => session?.setMask("keyboard", 0));
  subscribeSync((s) => {
    syncState = s;
    if (!session) return;
    for (const id of ["snapshot-btn", "fs-snapshot-btn"]) document.getElementById(id)?.replaceWith(snapshotButton(id)); // 工具栏那个 + 全屏浮条那个
  });

  // 防误缩放（iPad 双击 / 捏合）：CSS 里 touch-action 管双击，这里拦 Safari 的捏合手势
  for (const t of ["gesturestart", "gesturechange"]) document.addEventListener(t, (e) => e.preventDefault(), { passive: false });
  const local = canWriteLocalFiles();
  for (const id of ["make-wafter", "unwrap-wafter"]) ($(id) as HTMLButtonElement).disabled = !local;
  $("tools-hint").hidden = local;
  $("make-wafter").addEventListener("click", () => { makeWafer().catch(toolErr); });
  const uploadInput = $<HTMLInputElement>("upload-file");
  $("upload-wafter").addEventListener("click", () => { uploadInput.value = ""; uploadInput.click(); });
  uploadInput.addEventListener("change", () => { const f = uploadInput.files?.[0]; if (f) uploadWafer(f).catch(toolErr); });
  $("clear-cache").addEventListener("click", () => { clearCache().catch(toolErr); });
  const capSel = $<HTMLSelectElement>("staging-cap");
  for (const c of STAGING_CAP_CHOICES) capSel.append(h("option", { value: String(c.bytes) }, c.label));
  capSel.value = String(stagingCapBytes());
  capSel.addEventListener("change", () => { setStagingCapBytes(Number(capSel.value)); banner("暂存区上限改了，重新载入页面后生效。", "warning"); });
  $("unwrap-wafter").addEventListener("click", () => { unwrapWafer().catch(toolErr); });
  const fileInput = $<HTMLInputElement>("local-file");
  $("open-local").addEventListener("click", () => { audioContext(); fileInput.click(); });
  fileInput.addEventListener("change", () => { const f = fileInput.files?.[0]; if (f) playLocal(f); });
  $("unlock").addEventListener("click", () => { unlockTitles().catch((e) => banner(errorText(e))); });

  // store 先建、再 initAuth（登录回跳失败要有地方报）
  const store = getStore();
  // 这台设备记着口令（user 10-15 opt-in）：开页就拿回来，盘名 / 快照 / 存档都不用再问
  recallPassword().then((pw) => { if (!pw) return; setPassword(pw); remembered = true; renderAccount(); unlockTitles().catch(() => {}); }, (e) => console.warn("[remember]", e));
  watchPantry();
  mountSyncStatus({ onClick: () => { openSaveManager(saveManagerContext).catch((e) => banner(errorText(e))); }, signedIn: () => auth.isSignedIn() });
  // 没传上去 / 冲突的文件有几个：订阅 jars/ 和 crumbs/ 一直数着（本地写入、推完、冲突都会让 store 重发一帧）
  const pendingBy = new Map<string, number>();
  const pendingWatch = new Map<string, () => void>();
  const countPending = (folder: string) => {
    pendingWatch.get(folder)?.();
    pendingWatch.set(folder, store.files.watchFolder(folder, (snap) => {
      pendingBy.set(folder, snap.items.filter((it) => needsAttention(it.syncState)).length);
      setPending([...pendingBy.values()].reduce((a, b) => a + b, 0));
    }));
  };
  const recount = () => { countPending(jarFolder(PLATFORM_CODE.psp)); countPending(CRUMBS); };
  recount();
  // 游戏库只在订阅那一刻列一次云端：往 OneDrive 放了新盘要重列（user 10-14「gallery也需要refresh」）——按钮、回到前台、窗口得到焦点都重列一次
  $("refresh").addEventListener("click", () => watchPantry());
  const refocus = () => { if (!session && auth.isSignedIn() && document.visibilityState === "visible") watchPantry(); };
  document.addEventListener("visibilitychange", refocus);
  addEventListener("focus", refocus);
  renderAccount();
  renderLibrary();
  // 有东西在传时关标签页 / 刷新 → 浏览器自带的「离开页面？」（只在这时候挂；家规禁的是我们自己弹 alert / confirm）
  addEventListener("beforeunload", (e) => { if (inFlight()) { e.preventDefault(); e.returnValue = ""; } });
  // 没推完的（上次被打断的快照 / 存档）登录后、回到前台时自动续推——打断了也不用人去「推一把」
  // 推完重数一遍（pushAll 不一定让每个夹重发帧；重订阅 = 重新列一次）
  let pushing = false;
  const pushDirty = () => {
    if (pushing || inFlightFresh() || !auth.isSignedIn() || !navigator.onLine) return; // 卡死的在途上传（iOS 锁屏后永远不结束）不挡续推
    pushing = true;
    store.files.dirty.pushAll().catch((e) => console.warn("[pushAll]", e)).finally(() => { pushing = false; recount(); });
  };
  document.addEventListener("visibilitychange", () => { if (document.visibilityState === "visible") pushDirty(); });
  addEventListener("online", pushDirty);
  // 网络抖一下没传上去的：15 s 后再试一次；平时有没传上去的就每 45 s 试一次（10-14 user iPad：上传中途 Load failed 之后没人再传）
  let retryTimer = 0;
  onRetryWanted(() => { clearTimeout(retryTimer); retryTimer = window.setTimeout(pushDirty, 15_000); });
  setInterval(() => { if ([...pendingBy.values()].some((n) => n > 0)) pushDirty(); }, 45_000);
  auth.onAuthChanged(() => {
    renderAccount();
    renderLibrary();
    if (auth.isSignedIn()) {
      for (const f of [PANTRY, CRUMBS, JARS]) store.files.ensureFolder(f).catch((e) => console.warn("[ensureFolder]", f, e));
      store.files.drainOfflineQueue().catch((e) => console.warn("[drain]", e));
      pushDirty();
    }
  });
  try { await auth.initAuth(); } catch (e) { banner(`OneDrive 登录状态读取失败：${errorText(e)}`, "warning"); }
  try { await appState().init(); renderLibrary(); } catch (e) { console.warn("[app-state]", e); }
}

// 给自动化测试用的口子（scripts/first-light.ts）
(globalThis as Record<string, unknown>).kr = {
  stats: () => (session ? { ...session.stats(), note: lastNote } : null),
  async press(name: ButtonName, ms = 120) {
    if (!session) return;
    session.setMask("test", bit(name));
    await new Promise((r) => setTimeout(r, ms));
    session.setMask("test", 0);
  },
  inputMask: () => (session ? session.inputMask() : 0),
  snapshot: async () => (session ? (await session.snapshot()).state.length : 0),
  restoreFromServer: restoreFromDevServer,
  started: () => session !== null,
  pause: (p: boolean) => { session?.setPaused(p); renderToolbar(); },
  // 只在本机开发服务器上有：自动快照、测试口令（测试一律用假口令）
  ...(DEV_SERVER ? { autoSnapshot: () => snaps?.auto(), setTestPassword: (p: string) => setPassword(p), slots: () => snaps?.slots,
    askPassword: () => ensurePassword("测试"), hasPassword: () => getPassword() !== null, remembered: () => hasRememberedPassword(),
    resumeNewest: () => resumeNewest().then((s) => (s ? `${s.kind}${s.n}` : null)),
    // 探针：同一局里反复「存 → 恢复」n 次，每步报耗时和帧数（查「恢复两次之后核不应答」）
    async stateCycle(n: number) {
      const out: string[] = [];
      for (let i = 0; i < n && session; i++) {
        const t0 = performance.now();
        try {
          const st = await session.snapshot();
          const t1 = performance.now();
          await session.restore(st.state);
          out.push(`#${i} snap ${(t1 - t0).toFixed(0)}ms restore ${(performance.now() - t1).toFixed(0)}ms frames=${session.stats().frames}`);
        } catch (e) { out.push(`#${i} FAILED ${errorText(e)} frames=${session.stats().frames}`); break; }
        await new Promise((r) => setTimeout(r, 300));
      }
      return out;
    } } : {}),
  speed: (x: number) => { session?.setSpeed(x); renderToolbar(); },
};

